// Runs once on deploy: the library is already on `global` (function node `initialize`);
// this builds the table set eagerly so the first request does not pay for it.
const LIB = global.get('seatlab.lib');
if (!LIB) { node.error('lib missing'); return null; }
if (!global.get('seatlab.S')) global.set('seatlab.S', LIB.buildTables(LIB.dataRoot()));
global.set('seatlab.busy', null);          // a redeploy can never inherit a stale run lock
if (!global.get('seatlab.lessons')) global.set('seatlab.lessons', []);
global.set('seatlab.ready', true);
const S = global.get('seatlab.S');
node.status({fill:'green',shape:'dot',text:'lib ' + LIB.version + ' seats ' + S.T.seats.length});
return msg;

