// --- host shim: fs is a pre-declared sandbox var in Node-RED (see build.py LIBS),
// require('fs') under plain Node. typeof on an undeclared identifier never throws. ---
const FS = (typeof fs !== 'undefined') ? fs : require('fs');
const HTTP = (typeof http !== 'undefined') ? http : require('http');

// ---------------------------------------------------------------------------
// CSV / JSONL parsing (mirrors DuckDB read_csv_auto typing)
// ---------------------------------------------------------------------------

const NUMERIC_RE = /^-?\d+(\.\d+)?$/;

function coerceCsvValue(v) {
  if (v === '') return null;
  if (NUMERIC_RE.test(v)) return Number(v);
  if (/^true$/i.test(v)) return true;
  if (/^false$/i.test(v)) return false;
  return v;
}

// RFC-4180 parser: handles quoted fields with embedded commas/newlines/doubled quotes.
function parseCSV(text) {
  const rows = [];
  let field = '', row = [], inQuotes = false;
  const n = text.length;
  for (let i = 0; i < n; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else {
        field += c;
      }
      continue;
    }
    if (c === '"') { inQuotes = true; continue; }
    if (c === ',') { row.push(field); field = ''; continue; }
    if (c === '\r') { continue; }
    if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; continue; }
    field += c;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  if (rows.length === 0) return [];

  const header = rows[0];
  return rows.slice(1)
    .filter((r) => !(r.length === 1 && r[0] === ''))
    .map((r) => {
      const obj = {};
      header.forEach((h, idx) => { obj[h] = coerceCsvValue(r[idx] ?? ''); });
      return obj;
    });
}

function parseJSONL(text) {
  return text.split('\n')
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
    .map((l) => JSON.parse(l));
}

// ---------------------------------------------------------------------------
// Data root + table loading (duck.py build())
// ---------------------------------------------------------------------------

function dataRoot() {
  const candidates = [];
  if (typeof process !== 'undefined' && process.env && process.env.SEATLAB_DATA) {
    candidates.push(process.env.SEATLAB_DATA);
  }
  candidates.push('/data/challenge', '/data/challenge/data');
  for (const c of candidates) {
    try { if (c && FS.existsSync(c)) return c; } catch (e) { /* keep looking */ }
  }
  throw new Error('seatlab data root not found (checked SEATLAB_DATA, /data/challenge, /data/challenge/data)');
}

function loadTables(root) {
  const base = root.endsWith('/') ? root.slice(0, -1) : root;
  const readText = (name) => FS.readFileSync(`${base}/${name}`, 'utf8');
  const csv = (name) => parseCSV(readText(name));
  const jsonl = (name) => parseJSONL(readText(name));

  const technicians = csv('technicians.csv').map((t) => {
    const parts = String(t.shift).split('-');
    return { ...t, skill_list: String(t.skills).split('|'), shift_start: parts[0], shift_end: parts[1] };
  });
  const parts_stock = csv('parts_stock.csv').map((p) => ({ ...p, qty_available: p.qty_on_hand - p.qty_reserved }));
  const cabin_logs = csv('cabin_log_entries.csv').map((l) => ({
    ...l,
    defect_class: !String(l.text).toLowerCase().includes('cosmetic'),
  }));

  return {
    fleet: csv('fleet.csv'),
    seats: csv('seats.csv'),
    flights: csv('flights.csv'),
    stations: csv('stations.csv'),
    technicians,
    parts_catalog: csv('parts_catalog.csv'),
    parts_stock,
    cabin_logs,
    history: csv('maintenance_history.csv'),
    telemetry: jsonl('telemetry.jsonl'),
    telemetry_highrate: csv('telemetry_highrate.csv'),
    bite_events: jsonl('bite_events.jsonl'),
    cases: JSON.parse(readText('cases_seed.json')),
    economics: JSON.parse(readText('economics.json')),
    rag_chunks: jsonl('rag_chunks.jsonl'),
  };
}

// ---------------------------------------------------------------------------
// v_seat_leg_stats: per (seat_id, flight_id) leg aggregates over telemetry
// ---------------------------------------------------------------------------

function legStats(T) {
  const L = RULES.limits;
  const vibPhases = new Set(RULES.vibration_phases.phases);
  const groups = new Map(); // "seat_id|flight_id" -> samples[]

  for (const row of T.telemetry) {
    const key = row.seat_id + '|' + row.flight_id;
    let g = groups.get(key);
    if (!g) { g = { seat_id: row.seat_id, flight_id: row.flight_id, samples: [] }; groups.set(key, g); }
    g.samples.push(row);
  }

  const bySeat = new Map();
  for (const g of groups.values()) {
    const s = g.samples;
    const n = s.length;
    const col = (f) => s.map(f);
    const max = (f) => Math.max(...col(f));
    const min = (f) => Math.min(...col(f));
    const mean = (f) => col(f).reduce((a, v) => a + v, 0) / n;
    const countIf = (f, pred) => s.reduce((a, r) => a + (pred(f(r)) ? 1 : 0), 0);

    const act = (r) => r.actuator_current_a;
    const poserr = (r) => r.actuator_position_error_pct;
    const can = (r) => r.can_error_count;
    const seb = (r) => r.seb_temp_c;
    const usb = (r) => r.usb_pd_current_a;
    const usbv = (r) => r.usb_pd_voltage_v;
    const div = (r) => r.divider_position_error_pct;
    const cycles = (r) => r.actuation_cycles_total;

    const can_sum = col(can).reduce((a, v) => a + v, 0);
    const can_sum_vib = s.reduce((a, r) => a + (vibPhases.has(r.flight_phase) ? can(r) : 0), 0);

    const leg = {
      flight_id: g.flight_id,
      leg_start: min((r) => Date.parse(r.ts)),
      samples: n,
      act_max: max(act), act_mean: mean(act),
      can_max: max(can), can_mean: mean(can), can_sum, can_sum_vib,
      seb_max: max(seb), seb_mean: mean(seb),
      usb_max: max(usb), usb_mean: mean(usb), usb_v_min: min(usbv),
      div_max: max(div), div_mean: mean(div),
      poserr_max: max(poserr),
      act_breach: countIf(act, (v) => v > L.actuator_current_a.caution),
      poserr_breach: countIf(poserr, (v) => v > L.actuator_position_error_pct.caution),
      can_breach: countIf(can, (v) => v > L.can_error_count.caution),
      seb_breach: countIf(seb, (v) => v > L.seb_temp_c.shutdown),
      usb_breach: countIf(usb, (v) => v > L.usb_pd_current_a.abnormal_above),
      div_breach: countIf(div, (v) => v > L.divider_position_error_pct.confirms_defect_above),
      cycles_start: min(cycles), cycles_end: max(cycles),
    };

    if (!bySeat.has(g.seat_id)) bySeat.set(g.seat_id, []);
    bySeat.get(g.seat_id).push(leg);
  }

  for (const arr of bySeat.values()) arr.sort((a, b) => a.leg_start - b.leg_start);
  return bySeat;
}

// ---------------------------------------------------------------------------
// rising_run: longest strictly-increasing run ending within the last two legs
// ---------------------------------------------------------------------------

function risingRun(means, minRise = 0.0) {
  const n = means.length;
  let best = 0, bestRise = 0.0;
  let cur = 0, start = 0;
  for (let i = 1; i < n; i++) {
    if (means[i] > means[i - 1]) {
      cur += 1;
    } else {
      cur = 0; start = i;
    }
    if (i >= n - 2 && cur > best) {
      best = cur;
      bestRise = means[i] - means[start];
    }
  }
  const rise = Math.round(bestRise * 10000) / 10000;
  return bestRise >= minRise ? [best, rise] : [0, rise];
}

// ---------------------------------------------------------------------------
// seat_trend: per seat x family signal (duck.py _seat_trend)
// ---------------------------------------------------------------------------

const SIGNALS = { // family signal -> column prefix used in leg stats
  actuator_current_a: 'act', can_error_count: 'can', seb_temp_c: 'seb',
  usb_pd_current_a: 'usb', divider_position_error_pct: 'div',
};

function seatTrend(legs) {
  const minLegs = RULES.policy.min_trend_legs;
  const minRise = {};
  for (const [sig, v] of Object.entries(RULES.trend_min_rise)) minRise[sig] = v.min_rise;

  const out = new Map();
  for (const [seatId, legArr] of legs) {
    const bySignal = {};
    for (const [signal, p] of Object.entries(SIGNALS)) {
      const means = legArr.map((l) => l[`${p}_mean`]);
      const maxes = legArr.map((l) => l[`${p}_max`]);
      const [k, rise] = risingRun(means, minRise[signal]);

      let share = null;
      if (signal === 'can_error_count') {
        const tot = legArr.reduce((a, l) => a + l.can_sum, 0);
        share = tot ? legArr.reduce((a, l) => a + l.can_sum_vib, 0) / tot : null;
      }

      bySignal[signal] = {
        signal,
        legs: legArr.length,
        legs_rising: k,
        monotonic_degradation: k >= minLegs,
        rise,
        signal_max: Math.max(...maxes),
        mean_first: means[0],
        mean_last: means[means.length - 1],
        breach_count: legArr.reduce((a, l) => a + l[`${p}_breach`], 0),
        vibration_phase_share: share,
        per_leg_mean: means,
        per_leg_max: maxes,
      };
    }
    out.set(seatId, bySignal);
  }
  return out;
}

// ---------------------------------------------------------------------------
// v_fault_nff: n / nff / rate per fault code, plus (all) and (coded)
// ---------------------------------------------------------------------------

function faultNff(T) {
  const out = new Map();
  const isNff = (r) => r.outcome === 'NFF';
  const rate = (n, nff) => (n ? nff / n : 0);

  const byCode = new Map();
  for (const h of T.history) {
    const code = h.reported_fault_code;
    if (code === null || code === undefined) continue;
    if (!byCode.has(code)) byCode.set(code, []);
    byCode.get(code).push(h);
  }
  for (const [code, rowsForCode] of byCode) {
    const n = rowsForCode.length;
    const nff = rowsForCode.filter(isNff).length;
    out.set(code, { n, nff, rate: rate(n, nff) });
  }

  const allN = T.history.length;
  const allNff = T.history.filter(isNff).length;
  out.set('(all)', { n: allN, nff: allNff, rate: rate(allN, allNff) });

  const coded = T.history.filter((r) => r.reported_fault_code !== null && r.reported_fault_code !== undefined);
  const codedN = coded.length;
  const codedNff = coded.filter(isNff).length;
  out.set('(coded)', { n: codedN, nff: codedNff, rate: rate(codedN, codedNff) });

  return out;
}

// ---------------------------------------------------------------------------
// v_seat_breaches: per-seat breach totals across legs
// ---------------------------------------------------------------------------

function seatBreaches(legs) {
  const out = new Map();
  for (const [seatId, legArr] of legs) {
    const sum = (k) => legArr.reduce((a, l) => a + l[k], 0);
    const act = sum('act_breach'), poserr = sum('poserr_breach'), can = sum('can_breach');
    const seb = sum('seb_breach'), usb = sum('usb_breach'), div = sum('div_breach');
    out.set(seatId, { act, poserr, can, seb, usb, div, total: act + poserr + can + seb + usb + div });
  }
  return out;
}

// ---------------------------------------------------------------------------
// healthy seat: no BITE, no breach, no defect-class cabin log (dossier.py)
// ---------------------------------------------------------------------------

function isHealthy(S, seatId) {
  const hasBite = S.T.bite_events.some((b) => b.seat_id === seatId);
  const total = (S.breaches.get(seatId) || {}).total || 0;
  const hasDefectLog = S.T.cabin_logs.some((l) => l.seat_id === seatId && l.defect_class);
  return !hasBite && total === 0 && !hasDefectLog;
}

// ---------------------------------------------------------------------------
// buildTables: everything wired together
// ---------------------------------------------------------------------------

function buildTables(root) {
  const T = loadTables(root);
  const legs = legStats(T);
  const trend = seatTrend(legs);
  const nff = faultNff(T);
  const breaches = seatBreaches(legs);
  const seats = new Map(T.seats.map((s) => [s.seat_id, s]));
  return { T, legs, trend, nff, breaches, seats };
}

// ---------------------------------------------------------------------------
// Python-compatible formatting helpers (the response must render like the
// Python/Pydantic document: f"{x:.2f}", str(float), round(), isoformat)
// ---------------------------------------------------------------------------

const TEAM_ID = 'airbus-agents';
const DAY_MS = 86400000;

const fmt = (x, nd) => Number(x).toFixed(nd);                 // f"{x:.<nd>f}"
const pct0 = (x) => `${(Number(x) * 100).toFixed(0)}%`;       // f"{x:.0%}"
const pyRound = (x, nd) => Number(Number(x).toFixed(nd));     // round(x, nd)
const pyFloat = (x) => (Number.isInteger(x) ? Number(x).toFixed(1) : String(x)); // str(<float>)
const pyStr = (v) => (v === undefined || v === null ? 'None' : String(v));
const parseTs = (ts) => Date.parse(String(ts).replace(' ', 'T'));
const isoZ = (ms) => new Date(ms).toISOString().replace('.000Z', 'Z');
const utcDay = (ms) => { const d = new Date(ms); return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); };
const hhmm = (ms) => { const d = new Date(ms); return `${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')}`; };
const pad = (n, w) => String(n).padStart(w, '0');

// SHA-1: the work-order and second-opinion ids are hashes of the run id in the
// Python pipeline; no crypto module is available inside a Node-RED function node.
function sha1Hex(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.codePointAt(i);
    if (c > 0xffff) i++;
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(Math.floor(bitLen / Math.pow(2, i * 8)) & 0xff);

  let h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE, h3 = 0x10325476, h4 = 0xC3D2E1F0;
  const rol = (v, n) => ((v << n) | (v >>> (32 - n))) >>> 0;
  const w = new Array(80);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let i = 0; i < 16; i++) {
      w[i] = ((bytes[off + i * 4] << 24) | (bytes[off + i * 4 + 1] << 16) | (bytes[off + i * 4 + 2] << 8) | bytes[off + i * 4 + 3]) >>> 0;
    }
    for (let i = 16; i < 80; i++) w[i] = rol(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    let a = h0, b = h1, c = h2, d = h3, e = h4;
    for (let i = 0; i < 80; i++) {
      let f, k;
      if (i < 20) { f = (b & c) | (~b & d); k = 0x5A827999; }
      else if (i < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
      else { f = b ^ c ^ d; k = 0xCA62C1D6; }
      const t = (rol(a, 5) + (f >>> 0) + e + k + w[i]) >>> 0;
      e = d; d = c; c = rol(b, 30); b = a; a = t;
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0;
  }
  return [h0, h1, h2, h3, h4].map((x) => x.toString(16).padStart(8, '0')).join('');
}

// ---------------------------------------------------------------------------
// BM25-lite manual search over rag_chunks (replaces the Qdrant hybrid store)
// ---------------------------------------------------------------------------

const tokenise = (s) => String(s).toLowerCase().match(/[a-z0-9-]+/g) || [];

function bm25Index(S) {
  if (S.bm25) return S.bm25;
  const docs = S.T.rag_chunks.map((c) => {
    const blob = `${c.text} ${c.section} ${c.doc_id}`;
    const toks = tokenise(blob);
    const tf = {};
    for (const t of toks) tf[t] = (tf[t] || 0) + 1;
    return { chunk: c, blob, tf, len: toks.length };
  });
  const df = {};
  for (const d of docs) for (const t of Object.keys(d.tf)) df[t] = (df[t] || 0) + 1;
  const avgdl = docs.reduce((a, d) => a + d.len, 0) / (docs.length || 1);
  S.bm25 = { docs, df, avgdl, N: docs.length };
  return S.bm25;
}

function searchManuals(S, query, k, faultCode) {
  const K = k || 4, k1 = 1.2, b = 0.75;
  const ix = bm25Index(S);
  const qt = tokenise(query);
  const scored = ix.docs.map((d) => {
    let score = 0;
    for (const t of qt) {
      const f = d.tf[t];
      if (!f) continue;
      const idf = Math.log(1 + (ix.N - ix.df[t] + 0.5) / (ix.df[t] + 0.5));
      score += idf * ((f * (k1 + 1)) / (f + k1 * (1 - b + (b * d.len) / ix.avgdl)));
    }
    if (faultCode && d.blob.indexOf(faultCode) >= 0) score += 2.0;
    return { doc_id: d.chunk.doc_id, section: d.chunk.section, text: d.chunk.text, score };
  });
  scored.sort((a, c) => c.score - a.score);
  return scored.slice(0, K);
}

// ---------------------------------------------------------------------------
// Evidence grammar + resolver (guards/evidence.py)
// ---------------------------------------------------------------------------

const DOC_RE = /^(?:[A-Z]{2,4}-\d{2}-\d{2,4}(?:-\d{2,4})?(?:-R\d)?|OPS-[A-Z]+(?:-\d{2}|-POLICY)?|OPS-GROUNDTIME|TASK(?:CARD)?-[A-Z0-9-]+|PROC-[A-Z0-9-]+)$/;
const FILE_RE = /^[\w][\w.-]*\.(?:csv|jsonl|json|md|cypher)$/;
const METRIC_RE = /^[a-z_]+:[^\s=]+(?:=[^\s]+)?$/;
const LESSON_RE = /^lesson:[\w-]+$/;

function evidenceKind(id) {
  if (LESSON_RE.test(id)) return 'lesson';
  if (DOC_RE.test(id)) return 'doc';
  if (FILE_RE.test(id)) return 'file';
  if (METRIC_RE.test(id)) return 'metric';
  return null;
}

// ponytail: one data root per process (the Node-RED flow builds S once). A second
// dataRoot() in the same process would still see this listing; scope the cache on S
// the way bm25Index does if that ever becomes possible.
let _dataFiles = null;
function dataFiles() {
  if (_dataFiles) return _dataFiles;
  const names = new Set();
  const walk = (dir) => {
    for (const e of FS.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) walk(`${dir}/${e.name}`); else names.add(e.name);
    }
  };
  try { walk(dataRoot()); } catch (e) { /* no data dir: nothing resolves as a file */ }
  _dataFiles = names;
  return names;
}

function evidenceResolve(id, registry, lessonIds) {
  const lessons = new Set(lessonIds || []);
  const k = evidenceKind(id);
  if (k === null) return [false, 'does not match the evidence grammar'];
  if (k === 'doc') {
    const ok = RULES.doc_ids.indexOf(id) >= 0 || Object.prototype.hasOwnProperty.call(RULES.task_cards, id);
    return [ok, ok ? '' : 'unknown doc-id'];
  }
  if (k === 'file') {
    const ok = dataFiles().has(id);
    return [ok, ok ? '' : 'file not in data dir'];
  }
  if (k === 'lesson') {
    const ok = lessons.has(id);
    return [ok, ok ? '' : 'unknown lesson id'];
  }
  const i = id.indexOf('=');
  const key = i < 0 ? id : id.slice(0, i);
  const val = i < 0 ? '' : id.slice(i + 1);
  if (!Object.prototype.hasOwnProperty.call(registry || {}, key)) return [false, 'metric not computed by the dossier'];
  const got = String(registry[key]);
  if (val !== '') {
    const a = Number(val), b = Number(got);
    const close = (Number.isNaN(a) || Number.isNaN(b)) ? val === got : Math.abs(a - b) <= 0.011;
    if (!close) return [false, `value ${val} differs from computed ${got}`];
  }
  return [true, ''];
}

// ---------------------------------------------------------------------------
// Case context (graph/nodes.py::build_context)
// ---------------------------------------------------------------------------

function runId() {
  const d = new Date();
  const ts = `${d.getFullYear()}${pad(d.getMonth() + 1, 2)}${pad(d.getDate(), 2)}T${pad(d.getHours(), 2)}${pad(d.getMinutes(), 2)}${pad(d.getSeconds(), 2)}`;
  let rand = '';
  for (let i = 0; i < 6; i++) rand += Math.floor(Math.random() * 16).toString(16);
  return `${TEAM_ID}-${ts}-${rand}`;
}

function buildContext(S, body) {
  // I2: a non-object body (array, string, number, ...) or a non-string id must degrade, never throw.
  const req = (body && typeof body === 'object' && !Array.isArray(body)) ? body : {};
  const reasons = [];
  const asId = (v, label) => {
    if (v === undefined || v === null || v === '') return null;
    if (typeof v === 'string') return v;
    reasons.push(`${label} must be a string`);
    return null;
  };
  const caseIdIn = asId(req.case_id, 'case_id');
  const seatIdIn = asId(req.seat_id, 'seat_id');
  let caseRow = null;
  if (caseIdIn) {
    caseRow = S.T.cases.find((c) => c.case_id === caseIdIn) || null;
    if (caseRow === null) reasons.push(`unknown case_id ${caseIdIn}`);
  }
  if (!caseIdIn && !seatIdIn) caseRow = S.T.cases.find((c) => c.case_id === 'CASE-2026-0002') || null;
  let seatId = seatIdIn || (caseRow ? caseRow.seat_id : null);
  if (!seatId) reasons.push('no seat_id and unknown case: nothing to diagnose');
  seatId = seatId || 'UNKNOWN';
  const caseId = caseIdIn || (caseRow ? caseRow.case_id : `ADHOC-${seatId}`);
  if (caseRow && caseRow.seat_id !== seatId) reasons.push(`seat_id ${seatId} differs from case seat ${caseRow.seat_id}; using the requested seat`);
  const cut = seatId.lastIndexOf('-');                       // seat_id.rpartition("-")
  const reg = cut < 0 ? '' : seatId.slice(0, cut);
  const suite = cut < 0 ? seatId : seatId.slice(cut + 1);
  return {
    case_id: caseId, seat_id: seatId, registration: reg || '?', suite: suite || '?',
    fault_code_hint: caseRow ? caseRow.fault_code : null, case_row: caseRow,
    degraded_reasons: reasons, team_id: TEAM_ID, run_id: runId(),
  };
}

// ---------------------------------------------------------------------------
// Case dossier + evidence registry (data/dossier.py)
// ---------------------------------------------------------------------------

const SHORT = {
  actuator_current_a: 'actuator_current', can_error_count: 'can_error', seb_temp_c: 'seb_temp',
  usb_pd_current_a: 'usb_pd_current', divider_position_error_pct: 'divider_position_error',
};

const counter = (rows, key) => rows.reduce((a, r) => { a[r[key]] = (a[r[key]] || 0) + 1; return a; }, {});
const stationsOf = (S) => S.T.stations.reduce((a, s) => { a[s.iata] = s; return a; }, {});

function buildDossier(S, seatId, caseRow, lessons) {
  const ev = {};
  const fleet = S.nff.get('(all)');
  const seat = S.seats.get(seatId) || null;
  const base = {
    seat: null, bite_count: 0, bite_codes: {}, bite_phases: {}, bite_severity: {}, bite_events: [], trend: {},
    breaches: {}, cabin_logs: [], defect_logs: 0, seat_history: [], family_history: null, fleet_history: fleet,
    manuals: [], flights: [], stations: stationsOf(S), stock: [], catalog: {}, crew: [], economics: S.T.economics,
    lessons: [], fault_code: null, family: null, healthy: false, evidence: ev,
  };
  if (seat === null) {
    ev['seats:seat_not_found'] = seatId;
    ev['history:fleet:nff_rate'] = fmt(fleet.rate, 2);
    ev['OPS-NFF-01'] = '';
    return Object.assign(base, { healthy: true });
  }

  const reg = seat.registration;
  const bite = S.T.bite_events.filter((b) => b.seat_id === seatId).sort((a, b) => parseTs(a.ts) - parseTs(b.ts));
  const codes = counter(bite, 'fault_code');
  const phases = counter(bite, 'phase');
  const sev = counter(bite, 'severity');
  const hint = caseRow ? caseRow.fault_code : null;
  const noCodes = Object.keys(codes).length === 0;
  let faultCode = (caseRow && (Object.prototype.hasOwnProperty.call(codes, hint) || noCodes)) ? hint : null;
  if (!faultCode && !noCodes) {
    faultCode = Object.keys(codes).reduce((best, c) => (best === null || codes[c] > codes[best] ? c : best), null);
  }

  const trend = {};
  const tr = S.trend.get(seatId) || {};
  for (const sig of Object.keys(SIGNALS)) if (tr[sig]) trend[sig] = tr[sig];
  const br = S.breaches.get(seatId);
  const breaches = br ? Object.assign({}, br) : {};

  let fam = faultCode ? (RULES.families[faultCode] || null) : null;
  if (!faultCode && (breaches.total || 0)) {   // breach without BITE: family of the breached signal
    for (const code of Object.keys(RULES.families)) {
      const f = RULES.families[code];
      if (breaches[SIGNALS[f.signal]]) { faultCode = code; fam = f; ev['telemetry:family_from_breach_no_bite'] = code; break; }
    }
  }

  // dossier.py::_lessons(fault_code): only lessons of the just-computed family reach the dossier
  const les = (lessons || []).filter((l) => faultCode && l.fault_family === faultCode);

  const logs = S.T.cabin_logs.filter((l) => l.seat_id === seatId).sort((a, b) => String(a.reported_at).localeCompare(String(b.reported_at)));
  const defectLogs = logs.filter((l) => l.defect_class).length;
  const hist = S.T.history.filter((h) => h.seat_id === seatId).sort((a, b) => String(b.opened_at).localeCompare(String(a.opened_at)));
  const famh = faultCode ? (S.nff.get(faultCode) || null) : null;
  const flights = S.T.flights.filter((f) => f.registration === reg).sort((a, b) => parseTs(a.sta) - parseTs(b.sta));
  const catalog = S.T.parts_catalog.reduce((a, c) => { a[c.part_number] = c; return a; }, {});
  const crew = S.T.technicians.map((t) => ({
    technician_id: t.technician_id, name: t.name, station: t.station, skills: t.skill_list,
    authorisation: t.authorisation, shift: t.shift, shift_start: t.shift_start, shift_end: t.shift_end,
  }));
  const manuals = faultCode ? searchManuals(S, `${faultCode} ${fam ? fam.label : ''} fault isolation`, 4, faultCode) : [];
  const healthy = bite.length === 0 && (breaches.total || 0) === 0 && defectLogs === 0;

  // evidence registry — key strings are part of the contract, do not rename
  ev['bite_events.jsonl'] = '';
  ev['telemetry.jsonl'] = '';
  if (bite.length) { for (const c of Object.keys(codes)) ev[`bite:${c}x${codes[c]}`] = ''; } else { ev['bite:count'] = '0'; }
  for (const sig of Object.keys(trend)) {
    const t = trend[sig], s = SHORT[sig];
    ev[`telemetry:${s}_max`] = fmt(t.signal_max, 2);
    ev[`telemetry:${s}_legs_rising`] = String(t.legs_rising);
    ev[`telemetry:${s}_breaches`] = String(t.breach_count);
    if (t.vibration_phase_share !== null && t.vibration_phase_share !== undefined) ev['telemetry:can-error-vibration-share'] = fmt(t.vibration_phase_share, 3);
  }
  if (famh) {
    ev[`history:${faultCode}:nff_rate`] = fmt(famh.rate, 2);
    ev[`history:${faultCode}:n`] = String(famh.n);
    ev[`history:${faultCode}:nff`] = String(famh.nff);
  }
  ev['history:fleet:nff_rate'] = fmt(fleet.rate, 2);
  ev['maintenance_history.csv'] = '';
  if (hist.length) ev['history:seat_work_orders'] = String(hist.length);
  if (logs.length) { ev['cabin_log_entries.csv'] = ''; ev['cabin_log:defect_entries'] = String(defectLogs); }
  for (const l of les) ev[`lesson:${l.lesson_id}`] = '';
  if (fam) for (const d of [fam.isolated_by, fam.service_bulletin, fam.task_card]) if (d) ev[d] = '';
  ev['AMM-25-21-11'] = ''; ev['OPS-NFF-01'] = ''; ev['MEL-25-21-02'] = ''; ev['OPS-GT-01'] = '';

  return Object.assign(base, {
    seat, bite_count: bite.length, bite_codes: codes, bite_phases: phases, bite_severity: sev, bite_events: bite,
    trend, breaches, cabin_logs: logs, defect_logs: defectLogs, seat_history: hist, family_history: famh,
    fleet_history: fleet, manuals, flights, stock: S.T.parts_stock, catalog, crew, lessons: les,
    fault_code: faultCode, family: fam, healthy, evidence: ev,
  });
}

// ---------------------------------------------------------------------------
// Deterministic stage outputs (guards/fallbacks.py)
// ---------------------------------------------------------------------------

const NON_REMOVAL = ['CONNECTOR_TASK', 'DEFER_PER_MEL', 'CLEAN_AND_TEST', 'MONITOR'];

function eid(d, key) {
  const v = d.evidence[key];
  return (v === undefined || v === '') ? key : `${key}=${v}`;
}

function trendOf(d) {
  if (d.family) return d.trend[d.family.signal] || null;
  let best = null;
  for (const sig of Object.keys(d.trend)) {
    const t = d.trend[sig];
    if (!best || t.legs_rising > best.legs_rising || (t.legs_rising === best.legs_rising && t.breach_count > best.breach_count)) best = t;
  }
  return best;
}

function fallbackDiagnosis(run) {
  const d = run.D;
  const t = trendOf(d);
  const trend = {
    monotonic_degradation: !!(t && t.monotonic_degradation),
    legs_rising: t ? t.legs_rising : 0,
    vibration_phase_share: t ? (t.vibration_phase_share === undefined ? null : t.vibration_phase_share) : null,
  };
  if (d.seat === null) {
    return {
      fault_code: null, leading_cause: 'seat not found in seat master data; no data to diagnose', confidence: 0.5,
      evidence: [eid(d, 'seats:seat_not_found')], trend, reproducible_on_ground: null, bite_count: 0, signal_max: null, healthy: true,
    };
  }
  if (d.healthy || !d.family) {
    const ev = [eid(d, 'bite:count'), 'telemetry.jsonl', 'AMM-25-21-11'];
    if (d.cabin_logs.length) ev.push('cabin_log_entries.csv');
    return {
      fault_code: null,
      leading_cause: 'no active fault: no BITE events, all signals inside AMM-25-21-11 operating limits, no defect-class cabin-log entry',
      confidence: 0.9, evidence: ev, trend, reproducible_on_ground: null, bite_count: 0,
      signal_max: t ? t.signal_max : null, healthy: true,
    };
  }
  const fam = d.family, code = d.fault_code, causes = fam.causes;
  let cause = (code === 'F-25-2101' && trend.monotonic_degradation) ? causes[1] : causes[0];
  if (code === 'F-25-2140' && (trend.vibration_phase_share || 0) >= RULES.vibration_phases.service_share_min) {
    cause = `${causes[0]}; ${pct0(trend.vibration_phase_share)} of CAN errors occur in taxi/climb/descent (TSM-25-21-55: wiring/connector, not SCU)`;
  }
  const s = SHORT[fam.signal];
  const ev = d.bite_codes[code] ? [eid(d, `bite:${code}x${d.bite_codes[code] || 0}`)] : [eid(d, 'telemetry:family_from_breach_no_bite')];
  ev.push(eid(d, `telemetry:${s}_max`), eid(d, `telemetry:${s}_legs_rising`), eid(d, `telemetry:${s}_breaches`));
  if (trend.vibration_phase_share !== null) ev.push(eid(d, 'telemetry:can-error-vibration-share'));
  for (const k of ['isolated_by', 'service_bulletin']) if (fam[k]) ev.push(fam[k]);
  if (!fam.isolated_by) ev.push('AMM-25-21-11');
  if (d.cabin_logs.length) ev.push('cabin_log_entries.csv');
  for (const l of d.lessons) ev.push(eid(d, `lesson:${l.lesson_id}`));
  const conf = 0.6 + 0.1 * [
    d.bite_count > 0, (t ? t.breach_count : 0) > 0,
    trend.monotonic_degradation || (trend.vibration_phase_share || 0) > 0.7, d.defect_logs > 0,
  ].filter(Boolean).length;
  return {
    fault_code: code,
    leading_cause: cause + (fam.isolated_by ? '' : ' (no fault-isolation manual exists for this code; grounded in telemetry, BITE and history)'),
    confidence: Math.min(pyRound(conf, 2), 0.95), evidence: ev, trend,
    reproducible_on_ground: fam.reproducible_on_ground, bite_count: d.bite_count,
    signal_max: t ? t.signal_max : null, healthy: false,
  };
}

function justification(run) {
  const d = run.D, dx = run.stages.diagnosis;
  const fam = d.family || {};
  const repro = dx.reproducible_on_ground === null || dx.reproducible_on_ground === undefined ? false : !!dx.reproducible_on_ground;
  const mono = dx.trend.monotonic_degradation;
  const safety = !!fam.safety_relevant && ((d.breaches.total || 0) > 0 || d.bite_count > 0);
  return { '1a_reproducible_on_ground': repro, '1b_monotonic_degradation': mono, '1c_safety_not_clearable': safety, justified: repro || mono || safety };
}

function nffRiskFromHistory(d) {
  let base, hist;
  if (d.family_history && d.family_history.n >= 1) {
    base = Number(d.family_history.rate);
    hist = { similar_cases: d.family_history.n, nff_cases: d.family_history.nff, basis: `history:${d.fault_code}:nff_rate` };
  } else {
    base = Number(d.fleet_history.rate);
    hist = { similar_cases: d.fleet_history.n, nff_cases: d.fleet_history.nff, basis: 'history:fleet:nff_rate (no history for this code)' };
  }
  const deltas = d.lessons.map((l) => Number(l.prior_delta || 0));
  // mean, not sum: repeated identical outcomes converge
  const delta = deltas.length ? Math.max(-0.15, Math.min(0.15, deltas.reduce((a, v) => a + v, 0) / deltas.length)) : 0.0;
  if (delta) hist.lesson_prior_delta = pyRound(delta, 3);
  return [pyRound(Math.min(1.0, Math.max(0.0, base + delta)), 2), hist];
}

function fallbackNff(run) {
  const d = run.D, dx = run.stages.diagnosis;
  const P = RULES.policy, MEL = RULES.mel.items;
  if (dx.healthy || !d.family) {
    return {
      nff_risk: d.fleet_history ? pyRound(Number(d.fleet_history.rate), 2) : 0.0,
      decision: 'MONITOR',
      decision_rule: 'OPS-NFF-01: no fault signature on this seat; no removal candidate; monitor',
      reproducible_on_ground: null,
      history: {
        similar_cases: d.fleet_history ? d.fleet_history.n : 0, nff_cases: d.fleet_history ? d.fleet_history.nff : 0,
        basis: 'history:fleet:nff_rate (context only)',
      },
      mel_item: null, mel_category: null, suite_sellable: true, second_opinion_required: false,
      second_opinion_request: null, safety_relevant: false,
      citations: ['OPS-NFF-01', eid(d, 'history:fleet:nff_rate')],
    };
  }
  const fam = d.family, code = d.fault_code;
  const [risk, hist] = nffRiskFromHistory(d);
  const j = justification(run);
  let decision, rule;
  if (j.justified) {
    decision = code === 'F-23-3401' ? 'CLEAN_AND_TEST' : 'REPLACE_COMPONENT';
    const held = Object.keys(j).filter((k) => j[k] && k !== 'justified');
    rule = `OPS-NFF-01 rule 1 (${held.join(', ')}): removal justified`
      + (code === 'F-23-3401'
        ? ' — TSM-23-34-20 mandates cleaning + 30-min self-test before SEB removal; replacement conditional on idle temperature > 70 C'
        : `; ${fam.isolated_by || 'history'} procedure order before ${fam.part} replacement`);
  } else {
    decision = code === 'F-25-2140' ? 'CONNECTOR_TASK' : (code === 'F-23-3401' ? 'CLEAN_AND_TEST' : 'DEFER_PER_MEL');
    rule = `OPS-NFF-01 rule 2: not reproducible, no monotonic degradation, not safety-relevant — ${P.not_reproducible_action}`;
  }
  const melKey = fam.mel;
  let item;
  if (code === 'F-25-2140') item = j['1a_reproducible_on_ground'] ? melKey.reproducible : melKey.not_reproducible;
  else if (code === 'F-25-2101') item = d.bite_severity.MAJOR ? melKey.inoperative : melKey.degraded;
  else item = melKey.default;
  const mel = MEL[item];
  const second = risk > P.second_opinion_threshold;
  const req = second ? {
    request_id: `SO-${sha1Hex(run.ctx.run_id + code).slice(0, 8).toUpperCase()}`,
    addressee: `component owner / MRO (${(d.stations.FRA || {}).mro_partner || 'FACIS-MRO-Alpha'})`,
    question: `NFF risk ${risk} for ${code} on ${d.seat.seat_id}: confirm removal of ${fam.part} or advise task-card path`,
  } : null;
  const cites = ['OPS-NFF-01', eid(d, hist.basis.split(' ')[0]), 'maintenance_history.csv', 'MEL-25-21-02'];
  if (fam.isolated_by) cites.push(fam.isolated_by);
  for (const l of d.lessons) cites.push(eid(d, `lesson:${l.lesson_id}`));
  return {
    nff_risk: risk, decision, decision_rule: rule, reproducible_on_ground: dx.reproducible_on_ground,
    history: Object.assign({}, hist, j), mel_item: item, mel_category: mel.category, suite_sellable: !!mel.sellable,
    second_opinion_required: second, second_opinion_request: req, safety_relevant: !!fam.safety_relevant, citations: cites,
  };
}

// --- plan candidates: one feasibility record per arrival of this aircraft ---

const hms = (t) => {
  const m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/.exec(String(t));
  return ((Number(m[1]) * 60 + Number(m[2])) * 60 + (m[3] ? Number(m[3]) : 0)) * 1000;
};

function shiftOverlaps(tech, startL, endL) {
  const ss = hms(tech.shift_start), se = hms(tech.shift_end);
  for (const day of [utcDay(startL - DAY_MS), utcDay(startL), utcDay(endL)]) {
    const ws = day + ss;
    let we = day + se;
    if (we <= ws) we += DAY_MS;
    if (ws < endL && we > startL) return true;
  }
  return false;
}

// certifier may sign at shift start after the work slot, before departure (organisers' simplification)
function shiftStartsWithin(tech, endL, depL) {
  const ss = hms(tech.shift_start);
  for (const day of [utcDay(endL), utcDay(endL + DAY_MS)]) {
    const ws = day + ss;
    if (endL <= ws && ws <= depL) return true;
  }
  return false;
}

function planCandidates(run, task) {
  const d = run.D, G = RULES.ground;
  const need = task.duration_min + G.buffer_min;
  const row = run.ctx.case_row;
  // ponytail: settings.plan_from defaults to opened_at (organisers' sample semantics).
  // To make it configurable, read run.ctx.plan_from here and use row.latest_event_at
  // instead — that is the whole of fallbacks.py's `if settings.plan_from == "latest_event"`.
  let after = null;
  if (row) after = parseTs(row.opened_at);
  else if (d.bite_events.length) after = parseTs(d.bite_events[0].ts);

  const out = [];
  for (const f of d.flights) {
    const sta = parseTs(f.sta);
    if (after !== null && sta < after - 3600000) continue;
    const st = d.stations[f.arr_station] || {};
    const blockers = [];
    const groundMin = Number(f.ground_time_h_at_arrival) * 60;
    if (groundMin < need) blockers.push(`ground ${fmt(groundMin, 0)} min < task ${task.duration_min} + buffer ${G.buffer_min} min (OPS-GT-01)`);
    if (task.task_type === 'rotable' && !st.base_maintenance) {
      blockers.push(`${f.arr_station}: rotable replacement needs base maintenance (OPS-GT-01 rule 3); MRO partner ${pyStr(st.mro_partner)} capability not evidenced`);
    } else if (!st.line_maintenance) {
      blockers.push(`${f.arr_station}: no line maintenance (stations.csv)`);
    }
    const parts = [];
    for (const p of task.parts) {
      const s = d.stock.find((x) => x.station === f.arr_station && x.part_number === p.part_number) || null;
      const avail = s ? Number(s.qty_available) : 0;
      if (avail >= p.qty) parts.push({ part_number: p.part_number, qty: p.qty, source: 'ON_HAND', cost_eur: 0.0 });
      else {
        parts.push({ part_number: p.part_number, qty: p.qty, source: 'EXPEDITE', cost_eur: 0.0 });
        blockers.push(`${p.part_number} not available at ${f.arr_station} (on hand-reserved=${avail}); expedite ${G.expedite_surcharge_eur} EUR vs blocked suite ${G.blocked_suite_per_leg_eur} EUR/leg`);
      }
    }
    const off = Number(st.utc_offset_h || 0) * 3600000;
    const sl = sta + off, el = sta + need * 60000 + off;
    const depL = sta + Number(f.ground_time_h_at_arrival) * 3600000 + off;
    const crew = d.crew.filter((c) => c.station === f.arr_station);
    const leads = crew.filter((c) => task.skills.every((s) => c.skills.indexOf(s) >= 0) && shiftOverlaps(c, sl, el));
    const certs = crew.filter((c) => c.authorisation === task.authorisation && (shiftOverlaps(c, sl, el) || shiftStartsWithin(c, el, depL)));
    if (!leads.length) blockers.push(`no technician at ${f.arr_station} with ${task.skills.join('+')} on shift ${hhmm(sl)}-${hhmm(el)} local (technicians.csv)`);
    if (!certs.length) blockers.push(`no ${task.authorisation} certifying staff at ${f.arr_station} during the slot or starting shift before departure ${hhmm(depL)} local (technicians.csv)`);
    const lead = leads.length ? leads[0] : null;
    const cert = certs.find((c) => !lead || c.technician_id !== lead.technician_id) || (certs.length ? certs[0] : null);  // prefer a distinct certifier
    const technicians = [];
    if (lead) technicians.push({ technician_id: lead.technician_id, role: 'LEAD', skills_matched: task.skills, authorisation: lead.authorisation });
    if (cert) technicians.push({ technician_id: cert.technician_id, role: 'CERTIFYING', skills_matched: [], authorisation: cert.authorisation });
    const note = (!cert || shiftOverlaps(cert, sl, el)) ? '' : 'certifying signature at certifier shift start after the work slot (simplification, as in the organisers\' sample)';
    out.push({
      flight: f, station: f.arr_station, sta: isoZ(sta), slot_start: isoZ(sta), slot_end: isoZ(sta + need * 60000),
      ground_min: groundMin, parts, technicians, blockers, note,
    });
  }
  return out;
}

const price = (d, partNumber) => Number((d.catalog[partNumber] || {}).unit_price_eur || 0.0);

function fallbackPlan(run) {
  const d = run.D, nff = run.stages.nff, M = RULES.monitor;
  if (nff.decision === 'MONITOR' || !d.family) {
    return {
      task_card_id: M.task_card_id, task_duration_min: null, duration_is_assumed: false, buffer_min: 0,
      station: M.station, flight_id_before: null, slot_start: null, slot_end: null, parts: [], technicians: [],
      qualified_technician: false, feasible: true, blockers: [], alternatives: [],
      note: 'no action justified; continue monitoring', evidence: ['OPS-NFF-01'],
    };
  }
  const taskId = d.family.task_card, task = RULES.task_cards[taskId];
  const cands = planCandidates(run, task);
  const feas = cands.filter((c) => !c.blockers.length);
  const ev = ['flights.csv', 'parts_stock.csv', 'technicians.csv', 'stations.csv', 'OPS-GT-01', task.doc_id];
  for (const c of cands) d.evidence[`flights:${c.flight.flight_id}:ground_h`] = pyFloat(c.flight.ground_time_h_at_arrival);
  if (feas.length) {
    const c = feas[0];
    for (const p of c.parts) {
      const s = d.stock.find((x) => x.station === c.station && x.part_number === p.part_number);
      d.evidence[`stock:${c.station}:${p.part_number}:available`] = String(s.qty_available);
      ev.push(eid(d, `stock:${c.station}:${p.part_number}:available`));
    }
    ev.push(eid(d, `flights:${c.flight.flight_id}:ground_h`));
    return {
      task_card_id: taskId, task_duration_min: task.duration_min, duration_is_assumed: task.assumed,
      buffer_min: RULES.ground.buffer_min, station: c.station, flight_id_before: c.flight.flight_id,
      slot_start: c.slot_start, slot_end: c.slot_end,
      parts: c.parts.map((p) => ({ part_number: p.part_number, qty: p.qty, source: p.source, cost_eur: price(d, p.part_number) * p.qty })),
      technicians: c.technicians, qualified_technician: true, feasible: true, blockers: [], alternatives: [],
      note: c.note, evidence: ev,
    };
  }
  let best = null;
  for (const c of cands) {
    if (!best || (-c.blockers.length > -best.blockers.length)
      || (c.blockers.length === best.blockers.length && c.ground_min > best.ground_min)) best = c;
  }
  const alts = [];
  if (best) {
    const stn = best.station;
    ev.push(eid(d, `flights:${best.flight.flight_id}:ground_h`));
    const b1 = d.crew.filter((c) => c.station === stn && c.authorisation === task.authorisation);
    if (b1.length) {
      alts.push(`keep suite ${nff.suite_sellable === false ? 'blocked' : `under MEL ${pyStr(nff.mel_item)}`} and perform at ${stn} on shift ${b1[0].shift} local (${b1[0].technician_id} ${task.authorisation}); needs the next ground slot >= ${task.duration_min + 30} min`);
    }
    const first = task.parts.length ? task.parts[0].part_number : null;
    for (const s of d.stock) {
      if (s.part_number === first && Number(s.qty_available) > 0 && s.station !== stn) {
        const st = d.stations[s.station] || {};
        alts.push(`${s.part_number} available at ${s.station} (${s.qty_available}); ${st.base_maintenance ? 'base maintenance' : `line only, MRO ${pyStr(st.mro_partner)}`}`);
      }
    }
    if (nff.mel_item) alts.push(`MEL ${nff.mel_item}: category ${nff.mel_category}, sellable=${nff.suite_sellable ? 'True' : 'False'}`);
  }
  return {
    task_card_id: taskId, task_duration_min: task.duration_min, duration_is_assumed: task.assumed,
    buffer_min: RULES.ground.buffer_min, station: best ? best.station : 'N/A',
    flight_id_before: best ? best.flight.flight_id : null, slot_start: best ? best.slot_start : null,
    slot_end: best ? best.slot_end : null, parts: best ? best.parts : [], technicians: best ? best.technicians : [],
    qualified_technician: false, feasible: false,
    blockers: best ? best.blockers : ['no arrival of this aircraft after the latest event in flights.csv'],
    alternatives: alts.slice(0, 4), note: 'no feasible slot on the known rotation', evidence: ev,
  };
}

const ROOT_CAUSE = {
  'F-25-2140': 'connector locking clip not engaged (SB-25-2140-R1)',
  'F-25-2101': 'actuator gearbox wear confirmed; no obstruction found (TSM-25-21-40)',
  'F-23-3401': 'blocked SEB cooling path; idle temperature within limit after cleaning (TSM-23-34-20)',
  'F-25-2166': 'PSU/USB-PD module failing to current-limit; load test nominal after replacement',
  'F-25-2188': 'divider drive belt slip confirmed; stow position reached after replacement (TSM-25-21-88)',
};

function fallbackExecution(run) {
  const d = run.D, nff = run.stages.nff, plan = run.stages.plan;
  if (nff.decision === 'MONITOR' || plan.task_card_id === 'NONE') {
    return {
      work_order_id: null, task_card_id: 'NONE', station: 'N/A', outcome: 'NO_ACTION', functional_test_passed: true,
      measurement: null, root_cause: null, steps: [], evidence: ['OPS-NFF-01'],
    };
  }
  const task = RULES.task_cards[plan.task_card_id], acc = task.acceptance;
  if (!plan.feasible) {
    return {
      work_order_id: null, task_card_id: plan.task_card_id, station: plan.station, outcome: 'DEFERRED',
      functional_test_passed: false, measurement: null, root_cause: null,
      steps: task.steps.map((s, i) => ({ step_no: i + 1, text: s, status: 'PLANNED' })),
      evidence: [task.doc_id, 'OPS-GT-01'],
    };
  }
  // ponytail: simulated measurement at the acceptance nominal — the exercise has no live test equipment
  const m = ('nominal' in acc)
    ? { name: acc.measurement, value: pyRound(acc.nominal + 0.1, 1), unit: acc.unit, nominal: acc.nominal, tolerance: acc.tolerance === undefined ? null : acc.tolerance }
    : { name: acc.measurement, value: pyRound(acc.max * 0.85, 2), unit: acc.unit, nominal: acc.max, tolerance: null };
  const wo = `WO-9${pad(Number(BigInt(`0x${sha1Hex(run.ctx.run_id)}`) % 10000n), 4)}`;
  return {
    work_order_id: wo, task_card_id: plan.task_card_id, station: plan.station, outcome: 'CONFIRMED_FAULT',
    functional_test_passed: true, measurement: m, root_cause: ROOT_CAUSE[d.fault_code] || 'defect confirmed',
    steps: task.steps.map((s, i) => ({ step_no: i + 1, text: s, status: 'DONE' })), evidence: [task.doc_id],
  };
}

function fallbackLearning(run) {
  const d = run.D, nff = run.stages.nff, plan = run.stages.plan, ex = run.stages.execution, dx = run.stages.diagnosis;
  const E = d.economics;
  const removal = Number(E.unscheduled_removal_cost), shop = Number(E.nff_shop_test_cost), rate = Number(E.line_labour_cost_per_hour);
  const labour = (plan.feasible && plan.task_card_id !== 'NONE') ? pyRound(((plan.task_duration_min || 0) / 60) * rate, 2) : 0.0;
  const parts = plan.feasible ? pyRound(plan.parts.reduce((a, p) => a + price(d, p.part_number) * p.qty, 0), 2) : 0.0;
  const actual = pyRound(labour + parts, 2);
  const cf = removal + shop, cfW = pyRound(removal + nff.nff_risk * shop, 2);
  const monitor = nff.decision === 'MONITOR';
  const saving = monitor ? 0.0 : pyRound(cf - actual, 2);
  const avoided = !monitor && NON_REMOVAL.indexOf(nff.decision) >= 0 && nff.nff_risk > 0;
  const ev = ['economics.json', 'OPS-NFF-01', eid(d, 'history:fleet:nff_rate')];
  if (d.fault_code) ev.push(`history:${d.fault_code}:nff_rate` in d.evidence ? eid(d, `history:${d.fault_code}:nff_rate`) : 'maintenance_history.csv');
  let fb;
  if (monitor) {
    fb = `no fault signature: no removal contemplated, saving 0 (a removal + shop test would have cost ${fmt(cf, 0)} EUR); keep monitoring per AMM-25-21-11 limits`;
  } else if (ex.outcome === 'DEFERRED') {
    fb = `plan infeasible on the known rotation (${plan.blockers.slice(0, 2).join('; ')}); ${nff.decision_rule.split(':')[0]} held; schedule the first alternative and keep the suite ${nff.suite_sellable === false ? 'blocked' : 'sellable under MEL'}`;
  } else {
    fb = `${nff.decision_rule.split(' — ')[0]} held; outcome ${ex.outcome}; next time flag this signature (${d.family ? d.family.signal : 'n/a'}, legs_rising=${dx.trend.legs_rising}, vibration share=${dx.trend.vibration_phase_share === null ? 'None' : dx.trend.vibration_phase_share}) before the crew report`;
  }
  const errs = (run.meta && run.meta.errors) || [];
  const deps = Array.from(new Set(errs
    .filter((e) => e.indexOf('Connect') >= 0 || e.toLowerCase().indexOf('refused') >= 0 || e.toLowerCase().indexOf('timed out') >= 0)
    .map((e) => e.split(':')[1].trim().split(' ')[0]))).sort();
  if (errs.length) {
    fb += ' | degraded: ' + (deps.length ? `unavailable dependency (${deps.join(', ')})` : `model stage errors: ${errs.slice(0, 2).map((e) => e.slice(0, 80)).join('; ')}`);
  }
  const delta = monitor ? 0.0 : (ex.outcome === 'NFF' ? 0.05 : ((ex.outcome === 'CONFIRMED_FAULT' && NON_REMOVAL.indexOf(nff.decision) >= 0) ? -0.05 : 0.0));
  const lesson = monitor ? null : {
    lesson_id: `L-${run.ctx.run_id.slice(-8)}`, fault_family: d.fault_code, seat_id: run.ctx.seat_id,
    signature: { legs_rising: dx.trend.legs_rising, vibration_phase_share: dx.trend.vibration_phase_share, signal_max: dx.signal_max },
    decision: nff.decision, outcome: ex.outcome, saving_eur: saving, prior_delta: delta, threshold_delta_pct: 0.0,
    feedback: fb, created_at: `${new Date().toISOString().slice(0, 19)}+00:00`, run_id: run.ctx.run_id,
  };
  return {
    nff_avoided: avoided, saving_eur: saving, cost_actual_eur: actual, cost_counterfactual_remove_now_eur: cf,
    cost_counterfactual_risk_weighted_eur: cfW,
    cost_model: { labour_eur: labour, part_eur: parts, removal_eur: removal, shop_test_eur: shop, labour_rate_eur_h: rate },
    feedback: fb, lesson, evidence: ev,
  };
}

// ---------------------------------------------------------------------------
// Response assembly (submission/assemble.py)
// ---------------------------------------------------------------------------

const stageName = { diagnosis: 'diagnosis', nff: 'nff_assessment', plan: 'repair_plan', execution: 'execution', learning: 'outcome_learning' };
const agentNo = { diagnosis: 1, nff: 2, plan: 3, execution: 4, learning: 5 };
const STAGES = [['diagnosis', 'diagnosis'], ['nff_assessment', 'nff'], ['repair_plan', 'plan'], ['execution', 'execution'], ['outcome_learning', 'learning']];

const without = (obj, keys) => Object.keys(obj).reduce((a, k) => { if (keys.indexOf(k) < 0) a[k] = obj[k]; return a; }, {});

function assemble(run) {
  const ctx = run.ctx;
  const outs = {};
  for (const [name, attr] of STAGES) outs[name] = (run.stages || {})[attr] || {};
  const rec = {};
  for (const r of run.trace || []) rec[r.stage] = r;
  const trace = STAGES.map(([name], i) => ({
    stage: name, agent: i + 1, status: 'complete', output: outs[name],
    duration_ms: rec[name] ? rec[name].duration_ms : 0, tool_calls: rec[name] ? rec[name].tool_calls : 0,
    retries: rec[name] ? rec[name].retries : 0, fallback: rec[name] ? rec[name].fallback : true,
  }));
  const ev = [], seen = new Set();
  for (const src of [outs.diagnosis.evidence, outs.nff_assessment.citations, outs.repair_plan.evidence, outs.execution.evidence, outs.outcome_learning.evidence]) {
    for (const e of src || []) if (e && !seen.has(e)) { seen.add(e); ev.push(e); }
  }
  const dx = outs.diagnosis, nf = outs.nff_assessment, pl = outs.repair_plan, ex = outs.execution, ln = outs.outcome_learning;
  const execOut = without(ex, ['evidence', 'steps']);
  if (ex.measurement && ex.measurement.unit === 'ohm') execOut.termination_measurement_ohms = ex.measurement.value;
  const learnOut = without(ln, ['evidence', 'lesson']);
  if (ln.lesson) learnOut.lesson_id = ln.lesson.lesson_id;
  const final = {
    team_id: ctx.team_id, case_id: ctx.case_id, seat_id: ctx.seat_id,
    diagnosis: {
      fault_code: dx.fault_code === undefined ? null : dx.fault_code, leading_cause: dx.leading_cause || '',
      confidence: dx.confidence === undefined ? 0.0 : dx.confidence, trend: dx.trend === undefined ? null : dx.trend,
      healthy: dx.healthy === undefined ? false : dx.healthy,
    },
    nff_assessment: {
      nff_risk: nf.nff_risk === undefined ? 0.0 : nf.nff_risk, decision: nf.decision || 'MONITOR',
      decision_rule: nf.decision_rule === undefined ? null : nf.decision_rule,
      second_opinion_required: nf.second_opinion_required === undefined ? false : nf.second_opinion_required,
      mel_item: nf.mel_item === undefined ? null : nf.mel_item,
      suite_sellable: nf.suite_sellable === undefined ? null : nf.suite_sellable,
      history: nf.history === undefined ? null : nf.history,
    },
    evidence_ids: ev.length ? ev : ['OPS-NFF-01'],
    repair_plan: without(pl, ['evidence']),
    execution: execOut,
    outcome_learning: learnOut,
    integrations: Object.assign({}, run.integrations),
  };
  const reasons = (ctx.degraded_reasons || []).slice();
  // M8: node_agent.js always clears run.violations[stage] before returning (empty on a passing
  // retry, explicitly [] on fallback), so this loop never fires on the live path. Kept for parity
  // with graph/nodes.py::assemble, which folds the same field from a run that can carry a
  // leftover violation.
  for (const k of Object.keys(run.violations || {})) if ((run.violations[k] || []).length) reasons.push(`${k}: ${run.violations[k][0]}`);
  return {
    team_id: ctx.team_id, run_id: ctx.run_id,
    degraded: !!(run.degraded || (ctx.degraded_reasons || []).length),
    degraded_reasons: reasons,
    timing_ms: {
      total: run.started ? Math.trunc(Date.now() - run.started) : 0,
      stages: trace.reduce((a, t) => { a[t.stage] = t.duration_ms; return a; }, {}),
    },
    trace, final_submission: final,
  };
}

// ---------------------------------------------------------------------------
// Python-flavoured rendering: guard messages interpolate Python reprs
// (True/False, 'quoted' strings, [lists], {dicts}) and the prompts embed
// json.dumps output (", " / ": " separators).
// ---------------------------------------------------------------------------

const pyBool = (b) => (b ? 'True' : 'False');

function pyRepr(v) {
  if (v === undefined || v === null) return 'None';
  if (typeof v === 'boolean') return pyBool(v);
  if (typeof v === 'number') return String(v);
  if (typeof v === 'string') return `'${v.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
  if (Array.isArray(v)) return `[${v.map(pyRepr).join(', ')}]`;
  return `{${Object.keys(v).map((k) => `${pyRepr(k)}: ${pyRepr(v[k])}`).join(', ')}}`;
}

// json.dumps(obj, default=str): same shape as JSON.stringify but with Python's separators.
// ponytail: JS cannot tell int 1 from float 1.0, so a whole float renders as "1" where
// Python writes "1.0". Prompt text only; nothing parses these numbers back.
function pyJson(v) {
  if (v === undefined || v === null) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'null';
  if (typeof v === 'string') return JSON.stringify(v);
  if (Array.isArray(v)) return `[${v.map(pyJson).join(', ')}]`;
  return `{${Object.keys(v).map((k) => `${JSON.stringify(k)}: ${pyJson(v[k])}`).join(', ')}}`;
}

const pick = (obj, keys) => keys.reduce((a, k) => { a[k] = (obj && obj[k] !== undefined) ? obj[k] : null; return a; }, {});
const dedupe = (arr) => Array.from(new Set(arr || []));
const lessonIdsOf = (d) => (d.lessons || []).map((l) => `lesson:${l.lesson_id}`);
const toolEvidenceOf = (run, stage) => new Set((((run.meta || {}).tool_evidence) || {})[stage] || []);

// ---------------------------------------------------------------------------
// Guards (guards/{diagnosis,nff,plan,execution,learning}.py) — same violation strings
// ---------------------------------------------------------------------------

function guardDiagnosis(run) {
  const d = run.D, x = run.stages.diagnosis, v = [];
  if (!x) return ['no diagnosis output'];
  if (!!x.healthy !== !!d.healthy) {
    v.push(`healthy must be ${pyBool(d.healthy)}: BITE events=${d.bite_count}, limit breaches=${d.breaches.total || 0}, defect-class cabin logs=${d.defect_logs}`);
  }
  if (d.healthy && x.fault_code) v.push('a healthy seat has no fault_code (use null)');
  if (!d.healthy) {
    const allowed = dedupe(Object.keys(d.bite_codes).concat(d.fault_code ? [d.fault_code] : []));
    if (allowed.indexOf(x.fault_code) < 0) v.push(`fault_code must be one latched on this seat: ${pyRepr(allowed.slice().sort())}`);
    const fam = d.family;
    if (fam && fam.isolated_by && (x.evidence || []).indexOf(fam.isolated_by) < 0) v.push(`cite the fault-isolation manual ${fam.isolated_by} in evidence`);
    if (fam && fam.do_not_replace_first && String(x.leading_cause).indexOf(fam.do_not_replace_first) >= 0 && String(x.leading_cause).indexOf(fam.part) < 0) {
      v.push(`the manual says not to blame ${fam.do_not_replace_first} first; name ${fam.part} / the connector path`);
    }
  }
  if (!(x.evidence || []).length) v.push('evidence must not be empty');
  const lessons = lessonIdsOf(d), tool = toolEvidenceOf(run, 'diagnosis');
  for (const e of x.evidence || []) {
    const [ok, why] = evidenceResolve(e, d.evidence, lessons);
    if (!ok && !tool.has(e)) v.push(`evidence id '${e}' does not resolve (${why})`);
  }
  if (!String(x.leading_cause || '').trim()) v.push('leading_cause is empty');
  return v;
}

const NFF_ALLOWED = ['CLEAN_AND_TEST', 'CONNECTOR_TASK', 'DEFER_PER_MEL', 'MONITOR', 'REPLACE_COMPONENT'];   // sorted(ALLOWED)

function guardNff(run) {
  const d = run.D, x = run.stages.nff, dx = run.stages.diagnosis, v = [];
  if (!x) return ['no nff output'];
  if (NFF_ALLOWED.indexOf(x.decision) < 0) v.push(`decision must be one of ${pyRepr(NFF_ALLOWED)}`);
  const healthy = dx ? dx.healthy : d.healthy;
  if (healthy && x.decision !== 'MONITOR') v.push('healthy seat => decision MONITOR');
  if (!healthy && x.decision === 'MONITOR') v.push('MONITOR is only valid for a healthy seat');
  if (!healthy && d.family) {
    const [risk, hist] = nffRiskFromHistory(d);
    if (Math.abs(x.nff_risk - risk) > 0.011) v.push(`nff_risk must be exactly ${pyFloat(risk)} (computed from ${hist.basis}, n=${hist.similar_cases}); copy that number`);
    const j = justification(run), rec = fallbackNff(run);
    if (x.decision === 'REPLACE_COMPONENT' && !j.justified) v.push(`REPLACE_COMPONENT requires OPS-NFF-01 rule 1a, 1b or 1c; none holds -> the policy recommends ${rec.decision}`);
    if (x.decision === 'CLEAN_AND_TEST' && d.fault_code !== 'F-23-3401') v.push(`CLEAN_AND_TEST is only for F-23-3401; the policy recommends ${rec.decision}`);
    if (x.decision === 'CONNECTOR_TASK' && ['F-25-2140', 'F-25-2101', 'F-25-2166'].indexOf(d.fault_code) < 0) v.push(`CONNECTOR_TASK does not apply to ${d.fault_code}; the policy recommends ${rec.decision}`);
    const thr = RULES.policy.second_opinion_threshold;
    if (!!x.second_opinion_required !== (x.nff_risk > thr)) v.push(`second_opinion_required must be ${pyBool(x.nff_risk > thr)} (risk ${pyFloat(x.nff_risk)} vs threshold ${pyFloat(thr)})`);
    if (x.second_opinion_required && !x.second_opinion_request) v.push('second opinion required but no request recorded (call request_second_opinion)');
    const items = RULES.mel.items;
    if (x.mel_item && !Object.prototype.hasOwnProperty.call(items, x.mel_item)) v.push(`unknown MEL item ${x.mel_item}`);
    if (x.mel_item && Object.keys(d.family.mel).map((k) => d.family.mel[k]).indexOf(x.mel_item) < 0) {
      v.push(`MEL item ${x.mel_item} does not belong to ${d.fault_code}; valid items ${pyRepr(d.family.mel)} (recommended ${rec.mel_item})`);
    }
    if (d.family.isolated_by && (x.citations || []).indexOf(d.family.isolated_by) < 0 && (x.citations || []).indexOf('OPS-NFF-01') < 0) {
      v.push(`cite OPS-NFF-01 and ${d.family.isolated_by}`);
    }
  }
  if (!(x.citations || []).length) v.push('citations must not be empty');
  const lessons = lessonIdsOf(d), tool = toolEvidenceOf(run, 'nff');
  for (const e of x.citations || []) {
    const [ok, why] = evidenceResolve(e, d.evidence, lessons);
    if (!ok && !tool.has(e)) v.push(`citation '${e}' does not resolve (${why})`);
  }
  return v;
}

function guardPlan(run) {
  const d = run.D, x = run.stages.plan, nff = run.stages.nff, v = [];
  if (!x) return ['no plan output'];
  const M = RULES.monitor;
  if (nff.decision === 'MONITOR' || !d.family) {
    if (x.task_card_id !== M.task_card_id || x.station !== M.station || (x.parts || []).length || (x.technicians || []).length || !x.feasible) {
      v.push(`MONITOR plan must use sentinels task_card_id=${M.task_card_id}, station=${M.station}, no parts/technicians, feasible=true`);
    }
    return v;
  }
  const task = RULES.task_cards[x.task_card_id];
  if (!task) return [`unknown task card ${x.task_card_id}`];
  if (x.task_card_id !== d.family.task_card) v.push(`task card for ${d.fault_code} is ${d.family.task_card}`);
  if (!!x.feasible !== !(x.blockers || []).length) v.push('feasible must be true iff blockers is empty');
  const cands = new Map();
  for (const c of planCandidates(run, task)) cands.set(c.flight.flight_id, c);
  if (x.feasible) {
    const c = cands.get(x.flight_id_before);
    if (!c) v.push(`flight_id_before ${x.flight_id_before} is not an arrival of this aircraft after the case opened`);
    else {
      if (c.blockers.length) v.push(`candidate ${x.flight_id_before} is not feasible: ${pyRepr(c.blockers)}`);
      if (x.station !== c.station) v.push(`station must be the arrival station ${c.station}`);
      const ss = x.slot_start ? Date.parse(x.slot_start) : NaN, se = x.slot_end ? Date.parse(x.slot_end) : NaN;
      if (!ss || !se || (se - ss) < (task.duration_min + RULES.ground.buffer_min) * 60000) v.push('slot must be at least task duration + 30 min buffer');
      if (se && se > Date.parse(c.sta) + Number(c.flight.ground_time_h_at_arrival) * 3600000) v.push('slot exceeds the ground time');
      const roles = (x.technicians || []).map((t) => t.role);
      if (roles.indexOf('LEAD') < 0 || roles.filter((r) => r === 'CERTIFYING').length !== 1) v.push('plan needs one LEAD and exactly one CERTIFYING technician');
      for (const t of x.technicians || []) if (t.role === 'CERTIFYING' && t.authorisation !== task.authorisation) v.push(`certifier must be ${task.authorisation}`);
      const got = new Set((x.parts || []).map((p) => p.part_number));
      const missing = task.parts.map((p) => p.part_number).filter((pn) => !got.has(pn)).sort();
      if (missing.length) v.push(`missing parts ${pyRepr(missing)}`);
    }
  } else {
    const feas = Array.from(cands.keys()).filter((fid) => !cands.get(fid).blockers.length);
    if (feas.length) v.push(`a feasible candidate exists (${feas[0]}); the plan must use it instead of declaring infeasibility`);
    if (!(x.blockers || []).length) v.push('infeasible plan must list blockers');
    if (!(x.alternatives || []).length) v.push('infeasible plan must propose alternatives');
  }
  if (task.assumed && !x.duration_is_assumed) v.push('duration_is_assumed must be true for a procedure without a task card');
  for (const e of x.evidence || []) {
    const [ok, why] = evidenceResolve(e, d.evidence, []);
    if (!ok) v.push(`evidence id '${e}' does not resolve (${why})`);
  }
  return v;
}

function guardExecution(run) {
  const x = run.stages.execution, plan = run.stages.plan, nff = run.stages.nff, v = [];
  if (!x) return ['no execution output'];
  if (nff.decision === 'MONITOR' || plan.task_card_id === 'NONE') {
    if (x.outcome !== 'NO_ACTION' || !x.functional_test_passed || x.work_order_id) v.push('MONITOR => outcome NO_ACTION, functional_test_passed true, no work order');
    return v;
  }
  if (!plan.feasible && x.outcome !== 'DEFERRED') v.push('infeasible plan => outcome DEFERRED');
  if (plan.feasible && x.outcome === 'DEFERRED') v.push('feasible plan cannot be DEFERRED');
  if (plan.feasible && x.outcome === 'NO_ACTION') v.push('NO_ACTION is only for MONITOR');
  if (x.task_card_id !== plan.task_card_id || x.station !== plan.station) v.push('execution must reference the planned task card and station');
  if (plan.feasible) {
    if (!x.work_order_id) v.push('a performed task needs a work_order_id');
    const task = RULES.task_cards[plan.task_card_id], acc = (task ? task.acceptance : {}) || {};
    if (x.measurement) {
      const m = x.measurement;
      if ('nominal' in acc && acc.tolerance !== undefined && acc.tolerance !== null && Math.abs(m.value - acc.nominal) > acc.tolerance) {
        v.push(`measurement ${pyFloat(m.value)} outside ${acc.nominal} +/- ${acc.tolerance}`);
      }
      if ('max' in acc && m.value > acc.max && x.functional_test_passed) v.push(`measurement ${pyFloat(m.value)} above acceptance max ${acc.max} but test marked passed`);
    } else if (x.outcome === 'CONFIRMED_FAULT') v.push('a performed task needs the acceptance measurement');
    if (x.outcome === 'CONFIRMED_FAULT' && !x.functional_test_passed) v.push('CONFIRMED_FAULT with a repaired unit must pass the functional test');
  }
  return v;
}

function guardLearning(run) {
  const x = run.stages.learning, nff = run.stages.nff, ex = run.stages.execution, v = [];
  if (!x) return ['no learning output'];
  if (Math.abs(x.saving_eur - pyRound(x.cost_counterfactual_remove_now_eur - x.cost_actual_eur, 2)) > 0.011 && !(nff.decision === 'MONITOR' && x.saving_eur === 0)) {
    v.push('saving_eur must equal counterfactual - actual');
  }
  const ref = fallbackLearning(run);
  if (Math.abs(x.cost_actual_eur - ref.cost_actual_eur) > 0.011 || Math.abs(x.cost_counterfactual_remove_now_eur - ref.cost_counterfactual_remove_now_eur) > 0.011) {
    v.push(`costs must be computed from economics.json and the plan (actual ${pyFloat(ref.cost_actual_eur)}, counterfactual ${pyFloat(ref.cost_counterfactual_remove_now_eur)})`);
  }
  if (nff.decision === 'MONITOR' && x.nff_avoided) v.push('MONITOR: no removal was contemplated, nff_avoided must be false');
  if (nff.decision === 'REPLACE_COMPONENT' && x.nff_avoided) v.push('a removal was performed: nff_avoided must be false');
  if (x.lesson) {
    if (Math.abs(x.lesson.prior_delta) > 0.15) v.push('lesson prior_delta must be within +/-0.15');
    if (ex.outcome === 'NFF' && x.lesson.prior_delta < 0) v.push('an NFF outcome cannot lower the NFF prior');
    if (ex.outcome === 'CONFIRMED_FAULT' && NON_REMOVAL.indexOf(nff.decision) >= 0 && x.lesson.prior_delta > 0) v.push('a confirmed defect fixed without removal cannot raise the NFF prior');
  }
  if (!String(x.feedback || '').trim()) v.push('feedback is empty');
  return v;
}

const guards = { diagnosis: guardDiagnosis, nff: guardNff, plan: guardPlan, execution: guardExecution, learning: guardLearning };

// ---------------------------------------------------------------------------
// Prompts (graph/prompts.py) — one system prompt + one dossier prefix per run,
// then a short instruction per stage. The prefix must be byte-identical across
// the five calls so Ollama reuses the KV cache.
// ---------------------------------------------------------------------------

const SYSTEM = `You are the reasoning engine of a five-agent aircraft cabin maintenance workflow (Airbus AI Challenge, FACIS; synthetic data). You act as agents 1 Diagnose, 2 Judge, 3 Plan, 4 Execute, 5 Learn in turn.
RULES: cite evidence ids EXACTLY as listed in ALLOWED_EVIDENCE / REQUIRED_EVIDENCE or returned by tools (never invent ids or numbers; dossier field names are not ids). Numbers come from the dossier/tools; you interpret them. Max one tool round per agent; prose = one short sentence.
DOMAIN [doc ids]: limits [AMM-25-21-11] actuator >3.5 A caution/4.5 A cutout, position error >5 %, CAN >20/h; SEB shutdown >78 C [TSM-23-34-20]; divider error >10 % [TSM-25-21-88].
F-25-2140 [TSM-25-21-55, SB-25-2140-R1]: CAN bursts in taxi/climb/descent (~0 in cruise) = connector DA-CON-3390 / harness DA-HRN-7712 clip defect, NOT the SCU; not reproducible on ground.
F-25-2101 [TSM-25-21-40]: rising current over legs = actuator DA-ACT-2201 gearbox wear; never blame the SCU first. F-23-3401 [TSM-23-34-20]: blocked SEB cooling path; bench test passes (NFF trap); clean + 30-min self-test first.
F-25-2166: NO manual; use telemetry (USB >3.0 A vs fleet max 2.8 A), BITE, history (PSU DA-PSU-5150 / harness). F-25-2188 [TSM-25-21-88]: safety-relevant, suite not sellable [MEL-25-21-02 25-21-02e].
healthy=true in the dossier => fault_code null, decision MONITOR, no action; healthy=false => MONITOR forbidden.
OPS-NFF-01: removal justified iff 1a reproducible on ground OR 1b monotonic degradation >=3 legs OR 1c safety-relevant not clearable; else rule 2 = task card + 10-leg monitoring (decision CONNECTOR_TASK for F-25-2140, CLEAN_AND_TEST for F-23-3401, DEFER_PER_MEL otherwise). Rule 4: NFF risk >0.6 => second opinion required.
OPS-GT-01: slot >= task + 30 min in a real ground time; rotable needs base maintenance; part on hand or expedite 2 200 EUR vs blocked suite 10 000 EUR/leg; crew with skills on shift + one B1. Costs: removal 3 800, shop test 1 450, labour 110 EUR/h [economics.json].`;

const STAGE_PROMPT = {
  diagnosis: 'AGENT 1 - DIAGNOSE. Name the fault code latched on this seat (or null if healthy) and the most likely cause with the manual that isolates it. Set reproducible_on_ground (false for vibration-only CAN and heat-soak SEB faults). confidence is a fraction 0.0-1.0. Call a tool only if a needed fact is missing from the dossier.',
  plan: 'AGENT 3 - PLAN. Call plan_candidates (it evaluates every arrival for the decision\'s task). Choose the first feasible candidate\'s flight_id, or set feasible=false and write the blockers of the best candidate plus 2-3 concrete alternatives (later shift with the named B1, another station holding the part, MEL deferral). Write a one-sentence note.',
  execution: 'AGENTS 4+5 - EXECUTE and LEARN. The task card was performed and the acceptance measurement recorded by the system; costs, saving and nff_avoided are computed by the system (both below). Agent 4: write the root cause in one sentence naming the component and the manual, and a one-sentence technician note. Agent 5: write one feedback sentence naming the OPS-NFF-01 rule that held and one detector improvement, and propose prior_delta in [-0.15, 0.15] (negative when a non-removal action confirmed the defect, positive after an NFF, 0 otherwise).',
  learning: 'AGENT 5 - LEARN. Costs, saving and nff_avoided are computed by the system (below). Write one feedback sentence naming the OPS-NFF-01 rule that held and one detector improvement, and propose prior_delta in [-0.15, 0.15].',
  nff: 'AGENT 2 - JUDGE. Apply OPS-NFF-01 to the diagnosis above. Call nff_history (use its computed_nff_risk exactly) and policy_check (it evaluates 1a/1b/1c and recommends a decision; you confirm or override with a reason). Decision map for a FAULTY seat: rule 1 holds -> REPLACE_COMPONENT (F-23-3401 -> CLEAN_AND_TEST); rule 1 fails -> CONNECTOR_TASK for F-25-2140, CLEAN_AND_TEST for F-23-3401, DEFER_PER_MEL otherwise. MONITOR is ONLY for healthy=true. \'Monitoring for 10 legs\' after a task card is part of CONNECTOR_TASK, not the MONITOR decision. Set second_opinion_required=true when risk > 0.6 (the system files the request). Cite OPS-NFF-01, the isolating manual and the history id.',
};

function dossierSummary(run) {
  const d = run.D, c = run.ctx, fam = d.family || {};
  const t = d.family ? (d.trend[fam.signal] || null) : null;
  return {
    case_id: c.case_id, seat_id: c.seat_id, registration: c.registration,
    case: c.case_row ? pick(c.case_row, ['opened_at', 'latest_event_at', 'latest_flight_id', 'event_count']) : null,
    seat: d.seat ? pick(d.seat, ['firmware_version', 'actuation_cycles', 'install_date']) : null,
    healthy: d.healthy, fault_code_candidate: d.fault_code,
    family: d.family ? pick(fam, ['label', 'signal', 'isolated_by', 'service_bulletin', 'task_card', 'part', 'safety_relevant', 'reproducible_on_ground']) : null,
    bite: { count: d.bite_count, by_code: d.bite_codes, by_phase: d.bite_phases, by_severity: d.bite_severity },
    trend_of_family_signal: t ? without(t, ['per_leg_max', 'per_leg_mean']) : null,
    breaches: Object.keys(d.breaches).reduce((a, k) => { if (d.breaches[k]) a[k] = d.breaches[k]; return a; }, {}),
    cabin_logs: d.cabin_logs.filter((l) => l.defect_class).map((l) => String(l.text).slice(0, 70)).slice(0, 2),
    seat_history: d.seat_history.slice(0, 3).map((h) => `${pyStr(h.work_order_id)} ${pyStr(h.reported_fault_code)} ${pyStr(h.action_taken)} ${pyStr(h.outcome)}`),
    family_history: d.family_history, fleet_nff_rate: d.fleet_history ? pyRound(Number(d.fleet_history.rate), 2) : null,
    lessons: d.lessons.slice(0, 3).map((l) => pick(l, ['lesson_id', 'decision', 'outcome', 'prior_delta'])),
  };
}

function allowedEvidence(run) {
  const d = run.D;
  const ids = Object.keys(d.evidence).map((k) => (d.evidence[k] === '' ? k : `${k}=${d.evidence[k]}`));
  const fixed = ['telemetry.jsonl', 'bite_events.jsonl', 'maintenance_history.csv', 'cabin_log_entries.csv', 'flights.csv', 'parts_stock.csv',
    'technicians.csv', 'stations.csv', 'economics.json', 'OPS-NFF-01', 'OPS-GT-01', 'MEL-25-21-02', 'AMM-25-21-11'];
  const manuals = d.manuals.map((m) => m.doc_id);
  const fam = d.family;
  const extra = [];
  if (fam && fam.isolated_by) extra.push(fam.isolated_by);
  if (fam && fam.service_bulletin) extra.push(fam.service_bulletin);
  if (fam) extra.push(fam.task_card);
  return ids.concat(fixed, manuals, extra);
}

function prefixMessage(run) {
  const allowed = dedupe(allowedEvidence(run)).sort();
  return `DOSSIER (computed from the dataset):\n${pyJson(dossierSummary(run))}\n\nALLOWED_EVIDENCE:\n${pyJson(allowed)}`;
}

function requiredEvidence(stage, run) {
  const d = run.D, fam = d.family;
  if (stage === 'diagnosis') {
    if (d.healthy || !fam) return d.seat ? ['bite:count=0', 'telemetry.jsonl', 'AMM-25-21-11'] : [];
    const req = Object.keys(d.evidence)
      .filter((k) => k.indexOf('bite:') === 0 || k.indexOf('telemetry:') === 0)
      .map((k) => (d.evidence[k] === '' ? k : `${k}=${d.evidence[k]}`))
      .slice(0, 6);
    req.push(fam.isolated_by || 'AMM-25-21-11');
    return req;
  }
  if (stage === 'nff') {
    if (d.healthy || !fam) return ['OPS-NFF-01'];
    return ['OPS-NFF-01', fam.isolated_by || 'AMM-25-21-11', `history:${d.fault_code}:nff_rate=${d.evidence[`history:${d.fault_code}:nff_rate`] || ''}`, 'MEL-25-21-02'];
  }
  return [];
}

function stageMessage(stage, run) {
  const parts = [STAGE_PROMPT[stage]];
  const req = requiredEvidence(stage, run);
  if (req.length) parts.push('REQUIRED_EVIDENCE (must all appear in your evidence/citations, copied exactly):\n' + pyJson(req));
  if (stage === 'nff' && run.D.family && !run.D.healthy) {
    const [risk, hist] = nffRiskFromHistory(run.D);
    const rec = fallbackNff(run), j = justification(run);
    parts.push('RULES-BASED GUIDE (system-computed; you confirm or override with a stated reason):\n' + pyJson({
      computed_nff_risk: risk, history: hist, ops_nff_01_evaluation: j, recommended_decision: rec.decision, recommended_mel_item: rec.mel_item,
      valid_mel_items_for_this_fault: run.D.family.mel, second_opinion_required: risk > 0.6,
    }));
  }
  const meta = run.meta || {};
  if (stage === 'execution' && meta.exec_preview) {
    parts.push('PERFORMED (system):\n' + pyJson(meta.exec_preview) + '\nCOMPUTED COSTS (system):\n' + pyJson(meta.cost_preview === undefined ? null : meta.cost_preview));
  }
  if (stage === 'learning' && meta.cost_preview) parts.push('COMPUTED (system):\n' + pyJson(meta.cost_preview));
  const fb = (run.violations || {})[stage];
  if (fb && fb.length) parts.push('YOUR PREVIOUS ANSWER FOR THIS AGENT WAS REJECTED BY THE RULES GUARD. Violations:\n- ' + fb.join('\n- ') + '\nFix them.');
  return parts.join('\n\n');
}

const prompts = {
  system: () => SYSTEM,
  prefix: prefixMessage,
  stage: stageMessage,
  allowed: (run) => dedupe(allowedEvidence(run)).sort(),
};

// ---------------------------------------------------------------------------
// Tools (tools/{diagnose,judge,plan}_tools.py) — six OpenAI-format functions.
// The model reads the dossier for facts; a tool answers what the dossier omits.
// ---------------------------------------------------------------------------

const TOOL_SCHEMAS = [
  {
    type: 'function',
    function: {
      name: 'seat_trend',
      description: 'Per-leg trend of a telemetry signal (actuator_current_a|can_error_count|seb_temp_c|usb_pd_current_a|divider_position_error_pct): legs_rising, monotonic flag, per-leg means, breaches, vibration share.',
      parameters: { type: 'object', properties: { signal: { type: 'string' } }, required: ['signal'] },
    },
  },
  {
    type: 'function',
    function: {
      name: 'search_manuals',
      description: 'Semantic search over manuals (AMM/TSM/MEL/SB/task cards/policies); optional fault_code filter.',
      parameters: { type: 'object', properties: { query: { type: 'string' }, fault_code: { type: ['string', 'null'], default: null } }, required: ['query'] },
    },
  },
  {
    type: 'function',
    function: {
      name: 'nff_history',
      description: 'History for a fault code: n, NFF, rate, fleet baseline and the computed (lesson-adjusted) NFF risk to use.',
      parameters: { type: 'object', properties: { fault_code: { type: 'string' } }, required: ['fault_code'] },
    },
  },
  {
    type: 'function',
    function: {
      name: 'policy_check',
      description: 'Evaluate OPS-NFF-01 rules 1a/1b/1c on the current diagnosis; returns which hold.',
      parameters: { type: 'object', properties: {}, required: [] },
    },
  },
  {
    type: 'function',
    function: {
      name: 'mel_lookup',
      description: 'MEL-25-21-02 items for a fault code: category, interval, sellable.',
      parameters: { type: 'object', properties: { fault_code: { type: 'string' } }, required: ['fault_code'] },
    },
  },
  {
    type: 'function',
    function: {
      name: 'plan_candidates',
      description: 'Evaluate every arrival of this aircraft after the case opened for the decision\'s task: slot, ground time, station capability, parts, crew, blockers. Pick one feasible candidate or report none.',
      parameters: { type: 'object', properties: {}, required: [] },
    },
  },
];

const TOOL_IMPL = {
  seat_trend(args, run) {
    const d = run.D, t = d.trend[args.signal];
    if (!t) return { error: `unknown signal ${args.signal}`, signals: Object.keys(d.trend) };
    const s = SHORT[args.signal];
    return {
      signal: t.signal, legs: t.legs, legs_rising: t.legs_rising, monotonic_degradation: t.monotonic_degradation, rise: t.rise,
      signal_max: t.signal_max, per_leg_mean: t.per_leg_mean.map((x) => pyRound(x, 2)), per_leg_max: t.per_leg_max.map((x) => pyRound(x, 2)),
      breach_count: t.breach_count, limit: RULES.limits[args.signal] || null, vibration_phase_share: t.vibration_phase_share,
      evidence_ids: [eid(d, `telemetry:${s}_max`), eid(d, `telemetry:${s}_legs_rising`), eid(d, `telemetry:${s}_breaches`)]
        .concat(t.vibration_phase_share === null || t.vibration_phase_share === undefined ? [] : [eid(d, 'telemetry:can-error-vibration-share')]),
    };
  },
  search_manuals(args, run) {
    const d = run.D;
    // ponytail: without the table set (run.S) there is no index to search; answer from the
    // manual hits the dossier already retrieved and say so.
    const hits = run.S
      ? searchManuals(run.S, args.query, 4, args.fault_code || null)
      : d.manuals;
    const out = hits.map((h) => ({ doc_id: h.doc_id, section: h.section === undefined ? null : h.section, text: String(h.text).slice(0, 700) }));
    const res = { hits: out, evidence_ids: dedupe(out.map((h) => h.doc_id)).sort() };
    if (!run.S) res.note = 'no search index in this run; dossier manual hits only';
    return res;
  },
  nff_history(args, run) {
    const d = run.D;
    const [risk, hist] = nffRiskFromHistory(d);
    const rows = [];
    const push = (code, r) => { if (r) rows.push({ fault_code: code, n: r.n, nff: r.nff, rate: pyRound(Number(r.rate), 3) }); };
    if (run.S) {
      if (run.S.nff.get(args.fault_code)) push(args.fault_code, run.S.nff.get(args.fault_code));
      push('(all)', run.S.nff.get('(all)'));
      push('(coded)', run.S.nff.get('(coded)'));
    } else {
      if (args.fault_code === d.fault_code) push(args.fault_code, d.family_history);
      push('(all)', d.fleet_history);
    }
    return {
      computed_nff_risk: risk, USE_THIS_EXACT_nff_risk: risk,
      note: '0.0 means no NFF in history for this code; that is a valid risk value',
      rows, history: hist,
      evidence_ids: [`history:${args.fault_code}:nff_rate=${d.evidence[`history:${args.fault_code}:nff_rate`] || ''}`,
        'history:fleet:nff_rate=' + (d.evidence['history:fleet:nff_rate'] || ''), 'maintenance_history.csv'],
    };
  },
  policy_check(args, run) {
    const P = RULES.policy, j = justification(run), d = run.D;
    let rec, why;
    if (d.healthy || !d.family) { rec = 'MONITOR'; why = 'healthy seat: no fault signature'; }
    else if (j.justified) {
      rec = d.fault_code === 'F-23-3401' ? 'CLEAN_AND_TEST' : 'REPLACE_COMPONENT';
      why = 'rule 1 holds (' + Object.keys(j).filter((k) => j[k] && k !== 'justified').join(', ') + ')'
        + (d.fault_code === 'F-23-3401' ? ': TSM-23-34-20 requires cleaning + self-test before SEB removal' : '');
    } else {
      rec = d.fault_code === 'F-25-2140' ? 'CONNECTOR_TASK' : (d.fault_code === 'F-23-3401' ? 'CLEAN_AND_TEST' : 'DEFER_PER_MEL');
      why = 'rule 2: none of 1a/1b/1c holds -> no LRU removal; task card + 10-leg monitoring (this is NOT the MONITOR decision)';
    }
    return {
      rules: { '1a': 'reproducible on ground', '1b': 'monotonic degradation >= 3 legs', '1c': 'safety-relevant and not clearable', '2': P.not_reproducible_action, '4': `NFF risk > ${P.second_opinion_threshold} -> second opinion` },
      evaluation: j, recommended_decision: rec, recommendation_reason: why,
      you_decide: 'confirm or override with a stated reason; MONITOR is invalid for a faulty seat',
      evidence_ids: ['OPS-NFF-01'],
    };
  },
  mel_lookup(args, run) {
    const fam = Object.prototype.hasOwnProperty.call(RULES.families, args.fault_code) ? RULES.families[args.fault_code] : undefined;
    const items = RULES.mel.items;
    if (!fam) return { error: 'unknown fault code' };
    const candidates = {};
    for (const k of Object.keys(fam.mel)) candidates[k] = Object.assign({ item: fam.mel[k] }, items[fam.mel[k]]);
    return { candidates, safety_relevant: fam.safety_relevant, evidence_ids: ['MEL-25-21-02'] };
  },
  plan_candidates(args, run) {
    const d = run.D;
    if (!d.family || run.stages.nff.decision === 'MONITOR') return { task: null, candidates: [], note: 'MONITOR: no task' };
    const task = RULES.task_cards[d.family.task_card];
    const cands = planCandidates(run, task);
    const feas = cands.filter((c) => !c.blockers.length).slice(0, 3);
    const infeas = cands.filter((c) => c.blockers.length)
      .sort((a, b) => (a.blockers.length - b.blockers.length) || (b.ground_min - a.ground_min)).slice(0, 2);
    const row = (c) => ({
      flight_id: c.flight.flight_id, station: c.station, sta_utc: String(c.sta).replace('T', ' ').slice(0, 16), ground_min: Math.trunc(c.ground_min),
      parts: c.parts.map((p) => `${p.part_number}:${p.source}`), crew: c.technicians.map((t) => `${t.technician_id}:${t.role}`), blockers: c.blockers,
    });
    return {
      task_card_id: d.family.task_card, duration_min: task.duration_min, assumed_duration: task.assumed,
      needs: { skills: task.skills, certifier: task.authorisation, capability: task.task_type },
      feasible_candidates: feas.map(row), best_infeasible: infeas.map(row), evaluated: cands.length,
      evidence_ids: ['flights.csv', 'parts_stock.csv', 'technicians.csv', 'stations.csv', 'OPS-GT-01', task.doc_id],
    };
  },
};

function callTool(name, args, run) {
  const fn = Object.prototype.hasOwnProperty.call(TOOL_IMPL, name) ? TOOL_IMPL[name] : undefined;
  if (!fn) return { error: `unknown tool ${name}` };
  return fn(args || {}, run);
}

const tools = { schemas: TOOL_SCHEMAS, call: callTool };

// ---------------------------------------------------------------------------
// Answer schemas + merge (graph/llm.py): the model writes judgement and
// narrative, the code keeps every measured fact.
// ---------------------------------------------------------------------------

// model_json_schema() of DiagnosisAnswer / NffAnswer / PlanAnswer / ExecutionAnswer
// (llm.py). Kept byte-identical to the Pydantic output — titles, anyOf-nullables,
// defaults and the absence of additionalProperties included; orce/test/schemas.test.mjs
// deep-equals these against the live models.
const NULLABLE = (t) => ({ anyOf: [{ type: t }, { type: 'null' }] });

const EXECUTION_SCHEMA = {
  description: 'Agents 4 and 5 share one narrative call: execution record + learning, both grounded in system-computed outcome and costs.',
  properties: {
    root_cause: { description: 'agent 4: one sentence naming the component and the manual; empty for NO_ACTION', title: 'Root Cause', type: 'string' },
    technician_note: { description: 'agent 4: one sentence a technician would write on the work order', title: 'Technician Note', type: 'string' },
    feedback: { description: 'agent 5: one sentence naming the OPS-NFF-01 rule that held and one detector improvement', title: 'Feedback', type: 'string' },
    prior_delta: { description: 'agent 5: within [-0.15, 0.15]; negative if a non-removal action confirmed the defect, positive after an NFF, else 0', title: 'Prior Delta', type: 'number' },
  },
  required: ['root_cause', 'technician_note', 'feedback', 'prior_delta'],
  title: 'ExecutionAnswer',
  type: 'object',
};

const SCHEMAS = {
  diagnosis: {
    properties: {
      fault_code: Object.assign(NULLABLE('string'), { description: 'fault code latched by this seat, or null for a healthy seat', title: 'Fault Code' }),
      leading_cause: { description: 'most likely cause, one sentence, name the component and the manual', title: 'Leading Cause', type: 'string' },
      confidence: { description: '0.0-1.0', maximum: 100, minimum: 0, title: 'Confidence', type: 'number' },
      reproducible_on_ground: Object.assign(NULLABLE('boolean'), { title: 'Reproducible On Ground' }),
      evidence_ids: { description: 'copied exactly from ALLOWED_EVIDENCE or tool results; include every id listed under REQUIRED_EVIDENCE', items: { type: 'string' }, title: 'Evidence Ids', type: 'array' },
    },
    required: ['fault_code', 'leading_cause', 'confidence', 'reproducible_on_ground', 'evidence_ids'],
    title: 'DiagnosisAnswer',
    type: 'object',
  },
  nff: {
    properties: {
      nff_risk: { description: 'copy computed_nff_risk from nff_history verbatim, even when it is 0.0', maximum: 1, minimum: 0, title: 'Nff Risk', type: 'number' },
      decision: { enum: ['CONNECTOR_TASK', 'REPLACE_COMPONENT', 'DEFER_PER_MEL', 'MONITOR', 'CLEAN_AND_TEST'], title: 'Decision', type: 'string' },
      decision_rule: { description: 'which OPS-NFF-01 rule fired and why, one sentence', title: 'Decision Rule', type: 'string' },
      mel_item: Object.assign(NULLABLE('string'), { title: 'Mel Item' }),
      second_opinion_required: { title: 'Second Opinion Required', type: 'boolean' },
      citations: { description: 'only ids from ALLOWED_EVIDENCE or tool results', items: { type: 'string' }, title: 'Citations', type: 'array' },
    },
    required: ['nff_risk', 'decision', 'decision_rule', 'mel_item', 'second_opinion_required', 'citations'],
    title: 'NffAnswer',
    type: 'object',
  },
  plan: {
    properties: {
      feasible: { title: 'Feasible', type: 'boolean' },
      flight_id_before: Object.assign(NULLABLE('string'), { description: 'flight_id of the chosen feasible candidate, or null', title: 'Flight Id Before' }),
      blockers: { items: { type: 'string' }, title: 'Blockers', type: 'array' },
      alternatives: { items: { type: 'string' }, title: 'Alternatives', type: 'array' },
      note: { default: '', title: 'Note', type: 'string' },
    },
    required: ['feasible', 'flight_id_before'],
    title: 'PlanAnswer',
    type: 'object',
  },
  execution: EXECUTION_SCHEMA,
  learning: EXECUTION_SCHEMA,
};

function parseAnswer(schema, content) {
  const text = String(content === undefined || content === null ? '' : content).trim();
  let obj = null;
  try { obj = JSON.parse(text); } catch (e) { obj = null; }
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    const a = text.indexOf('{'), b = text.lastIndexOf('}');
    if (a < 0 || b <= a) throw new Error(`unparseable answer: ${text.slice(0, 300)}`);
    obj = JSON.parse(text.slice(a, b + 1));
  }
  for (const k of schema.required || []) {
    if (obj[k] === undefined) throw new Error(`answer misses required field ${k}: ${text.slice(0, 300)}`);
  }
  return obj;
}

const clamp15 = (x) => Math.max(-0.15, Math.min(0.15, Number(x) || 0));

function merge(stage, run, ans, toolEvidence) {
  const d = run.D;
  if (stage === 'diagnosis') {
    const fb = fallbackDiagnosis(run);              // measured facts always come from the dossier
    let cause = String(ans.leading_cause || '').trim();
    if (d.family && !d.family.isolated_by && cause.toLowerCase().indexOf('manual') < 0) {
      cause += ' (no fault-isolation manual exists for this code; grounded in telemetry, BITE and history)';
    }
    const conf = Number(ans.confidence);
    return {
      fault_code: d.healthy ? null : ans.fault_code,
      leading_cause: cause, confidence: pyRound(conf > 1 ? pyRound(conf / 100, 2) : conf, 2),
      evidence: dedupe(ans.evidence_ids), trend: fb.trend, reproducible_on_ground: ans.reproducible_on_ground === undefined ? null : ans.reproducible_on_ground,
      bite_count: fb.bite_count, signal_max: fb.signal_max, healthy: d.healthy,
    };
  }
  if (stage === 'nff') {
    const fb = fallbackNff(run);
    const [risk, hist] = d.family ? nffRiskFromHistory(d) : [fb.nff_risk, fb.history];
    const MEL = RULES.mel.items;
    const item = Object.prototype.hasOwnProperty.call(MEL, ans.mel_item) ? ans.mel_item : fb.mel_item;
    const mel = item ? MEL[item] : null;
    const second = !!ans.second_opinion_required;
    let req = second ? fb.second_opinion_request : null;
    if (second && !req && d.family) {   // the Judge decided rule 4 applies: record the (mocked) cross-organisation request
      req = {
        request_id: `SO-${run.ctx.run_id.slice(-8)}`, addressee: 'component owner / MRO (FACIS federation partner)',
        question: `NFF risk ${pyFloat(ans.nff_risk)} for ${d.fault_code}: confirm removal of ${d.family.part} or advise task-card path`,
      };
    }
    return {
      nff_risk: pyRound(Number(ans.nff_risk), 2), decision: ans.decision, decision_rule: ans.decision_rule,
      reproducible_on_ground: run.stages.diagnosis ? run.stages.diagnosis.reproducible_on_ground : null,
      history: d.family ? Object.assign({}, hist, justification(run)) : fb.history,
      mel_item: item === undefined ? null : item, mel_category: mel ? mel.category : null,
      suite_sellable: mel ? !!mel.sellable : fb.suite_sellable, second_opinion_required: second, second_opinion_request: req,
      safety_relevant: d.family ? !!d.family.safety_relevant : false, citations: dedupe(ans.citations),
    };
  }
  if (stage === 'plan') {
    const fb = fallbackPlan(run);
    if (fb.task_card_id === 'NONE') return fb;                    // MONITOR sentinels are not negotiable
    const task = RULES.task_cards[fb.task_card_id];
    const cands = planCandidates(run, task);
    const chosen = (ans.feasible && ans.flight_id_before) ? (cands.find((c) => c.flight.flight_id === ans.flight_id_before) || null) : null;
    if (chosen && !chosen.blockers.length) {
      let plan = fallbackPlan(run);                               // recompute with the same evidence registry
      if (plan.flight_id_before !== chosen.flight.flight_id) {
        plan = Object.assign({}, plan, {
          flight_id_before: chosen.flight.flight_id, station: chosen.station, slot_start: chosen.slot_start, slot_end: chosen.slot_end,
          parts: chosen.parts.map((p) => Object.assign({}, p, { cost_eur: price(d, p.part_number) * p.qty })),
          technicians: chosen.technicians, note: chosen.note,
        });
      }
      return Object.assign({}, plan, { note: String(ans.note || plan.note).slice(0, 300), alternatives: (ans.alternatives || []).slice(0, 4) });
    }
    // infeasible (per the model) -> keep the deterministic best candidate but take the model's narrative
    return Object.assign({}, fb, {
      feasible: false, qualified_technician: false,
      blockers: (fb.blockers.length ? fb.blockers : (ans.blockers || [])).slice(0, 5),
      alternatives: ((ans.alternatives && ans.alternatives.length) ? ans.alternatives : fb.alternatives).slice(0, 4),
      note: String(ans.note || fb.note).slice(0, 300),
    });
  }
  if (stage === 'execution') {
    const fb = fallbackExecution(run);              // outcome + measurement come from the simulation
    if (fb.outcome === 'NO_ACTION') return fb;
    const note = String(ans.technician_note || '');
    const steps = fb.steps.concat((fb.steps.length && note) ? [{ step_no: fb.steps.length + 1, text: `Technician note: ${note.slice(0, 200)}`, status: 'DONE' }] : []);
    const rc = ans.root_cause || fb.root_cause;
    return Object.assign({}, fb, { root_cause: rc === null || rc === undefined ? null : String(rc).slice(0, 300), steps });
  }
  if (stage === 'learning') {
    const fb = fallbackLearning(run);
    const feedback = String(ans.feedback || '').slice(0, 400);
    const lesson = fb.lesson ? Object.assign({}, fb.lesson, { prior_delta: pyRound(clamp15(ans.prior_delta), 3), feedback }) : null;
    return Object.assign({}, fb, { feedback, lesson });
  }
  return null;
}

// ---------------------------------------------------------------------------
// Ollama HTTP client + stage runner (graph/llm.py, graph/nodes.py)
// ---------------------------------------------------------------------------

function ollamaChat(baseUrl, body, timeoutMs) {
  return new Promise((resolve, reject) => {
    let data;
    try { data = JSON.stringify(body); } catch (e) { return reject(new Error(`ollama request not serialisable: ${e.message}`)); }
    let req;
    try {
      req = HTTP.request(`${baseUrl}/api/chat`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) },
      }, (res) => {
        let text = '';
        res.setEncoding('utf8');
        res.on('data', (c) => { text += c; });
        res.on('end', () => {
          if (res.statusCode < 200 || res.statusCode >= 300) return reject(new Error(`ollama HTTP ${res.statusCode}: ${text.slice(0, 200)}`));
          try { resolve(JSON.parse(text)); } catch (e) { reject(new Error(`ollama returned invalid JSON: ${text.slice(0, 200)}`)); }
        });
      });
    } catch (e) { return reject(e); }
    req.setTimeout(timeoutMs, () => req.destroy(new Error('timeout')));
    req.on('error', reject);
    req.end(data);
  });
}

const TOOL_ROUND = ['diagnosis', 'nff', 'plan'];          // execute/learn only write narrative: one call each
const needSeconds = { diagnosis: 8, nff: 6, plan: 5, execution: 3.5, learning: 2.5 };   // nodes.py NEED_S
const ANSWER_ASK = 'Now give this agent\'s final answer as JSON in the required schema.';

function execPreview(run) {
  const fb = fallbackExecution(run);
  return { work_order_id: fb.work_order_id, outcome: fb.outcome, functional_test_passed: fb.functional_test_passed, measurement: fb.measurement };
}

function costPreview(run) {
  const prev = run.stages.execution;
  run.stages.execution = fallbackExecution(run);
  const fb = fallbackLearning(run);
  run.stages.execution = prev;
  return {
    nff_avoided: fb.nff_avoided, saving_eur: fb.saving_eur, cost_actual_eur: fb.cost_actual_eur,
    cost_counterfactual_remove_now_eur: fb.cost_counterfactual_remove_now_eur, cost_counterfactual_risk_weighted_eur: fb.cost_counterfactual_risk_weighted_eur,
  };
}

async function runStage(stage, run, opts) {
  const schema = SCHEMAS[stage];
  if (!schema) return null;
  const o = opts || {};
  const model = o.model || run.model;
  const baseUrl = o.baseUrl;
  run.meta = run.meta || {};
  if (stage === 'learning' && run.meta.exec_learn_answer) {          // already produced by the shared agent-4/5 call
    return { out: merge('learning', run, run.meta.exec_learn_answer, new Set()), calls: 0, timings: [] };
  }
  if (stage === 'execution') {
    run.meta.exec_preview = execPreview(run);
    run.meta.cost_preview = costPreview(run);
  }
  // ONE growing conversation per run (llm.py::conversation): every stage's exchange stays in
  // run.msgs, so agent 3 plans against the diagnosis and the decision it can read above it.
  // On a retry, drop this stage's previous exchange so the shared prefix stays clean.
  const msgs = run.msgs;
  for (let i = msgs.length - 1; i >= 0; i--) if (msgs[i]._stage === stage) msgs.splice(i, 1);
  const start = msgs.length;
  const tag = (m) => { m._stage = stage; return m; };
  const wire = (extra) => msgs.concat(extra || []).map((m) => { const c = Object.assign({}, m); delete c._stage; return c; });
  const timings = [];
  const toolEvidence = new Set();
  let calls = 0;
  // run.deadline gates *starting* a stage (nodes.py::remaining); a call already in flight runs to
  // the hard wall, as it does in Python, instead of being cut mid-generation at the soft deadline.
  const budget = () => Math.max(1, Math.min((run.wall || run.deadline) - Date.now(), 20000));
  const base = { model, stream: false, tools: TOOL_SCHEMAS, options: { temperature: 0, num_ctx: 8192, num_predict: 300 }, keep_alive: -1 };
  let ans;
  try {
    msgs.push(tag({ role: 'user', content: stageMessage(stage, run) }));

    if (TOOL_ROUND.indexOf(stage) >= 0) {
      const t0 = Date.now();
      const res = await ollamaChat(baseUrl, Object.assign({}, base, { messages: wire() }), budget());
      timings.push(Date.now() - t0);
      const m = (res && res.message) || {};
      msgs.push(tag(m));
      for (const tc of (m.tool_calls || []).slice(0, 4)) {
        calls += 1;
        const fn = tc.function || {};
        let args = fn.arguments;
        if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
        let result;
        try { result = callTool(fn.name, args || {}, run); } catch (e) { result = { error: `${e.name}: ${String(e.message).slice(0, 200)}` }; }
        for (const e of (result && result.evidence_ids) || []) toolEvidence.add(e);
        const tm = { role: 'tool', content: JSON.stringify(result).slice(0, 3000), tool_name: fn.name };
        if (tc.id) tm.tool_call_id = tc.id;        // langchain_ollama sends this; Ollama itself omits ids
        msgs.push(tag(tm));
      }
    }
    const ask = tag({ role: 'user', content: ANSWER_ASK });
    const t1 = Date.now();
    const res2 = await ollamaChat(baseUrl, Object.assign({}, base, { messages: wire([ask]), format: schema }), budget());
    timings.push(Date.now() - t1);
    ans = parseAnswer(schema, ((res2 && res2.message) || {}).content);
    msgs.push(ask);
    msgs.push(tag((res2 && res2.message) || { role: 'assistant', content: '' }));
  } catch (e) { msgs.length = start; throw e; }
  (run.meta.answers = run.meta.answers || {})[stage] = (run.meta.answers[stage] || []).concat([ans]);   // x-debug: the raw model answer per attempt
  (run.meta.timings = run.meta.timings || {})[stage] = (run.meta.timings[stage] || []).concat([timings]);
  if (stage === 'execution') run.meta.exec_learn_answer = ans;
  run.meta.tool_evidence = run.meta.tool_evidence || {};
  run.meta.tool_evidence[stage] = Array.from(toolEvidence).sort();
  return { out: merge(stage, run, ans, toolEvidence), calls, timings };
}

const LIB = {
  RULES, version: "0.1",
  parseCSV, parseJSONL, dataRoot, loadTables,
