// Agent 0: request -> run state. Loads the table set once, builds the context and the
// dossier, picks the model for this request and takes the single-run busy lock.
const LIB = global.get('seatlab.lib');
let S = global.get('seatlab.S');
if (!S) {
  S = LIB.buildTables(LIB.dataRoot());
  global.set('seatlab.S', S);
  global.set('seatlab.ready', true);
}

let body = msg.payload;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};

const ctx = LIB.buildContext(S, body);
const D = LIB.buildDossier(S, ctx.seat_id, ctx.case_row, global.get('seatlab.lessons') || []);
// graph/nodes.py::build_dossier_node — the "seat not found" reason lives in the node
if (!D.seat && ctx.degraded_reasons.join(' ').indexOf('seat not found') < 0) ctx.degraded_reasons.push('seat not found');

const headers = (msg.req && msg.req.headers) || {};
let model = headers['x-model'] || flow.get('MODEL') || 'qwen2.5:3b-instruct';

// G8 single-run lock: a second request while one is in flight answers deterministically.
// ponytail: a stale lock (crashed run that never reached assemble/degraded) is ignored after 60 s.
// I1: only the request that actually takes the lock may release it later — record that on the
// run itself, immediately, so a later throw (even the debug hook below) still carries it.
const busy = global.get('seatlab.busy');
let lock_owner = false;
if (busy && Date.now() - busy < 60000) {
  model = 'off';
  ctx.degraded_reasons.push('another run in progress; deterministic answer');
} else {
  global.set('seatlab.busy', Date.now());
  lock_owner = true;
}

const now = Date.now();
const run = {
  ctx, D, S, model, lock_owner,
  started: now, deadline: now + 26000, wall: now + 27500,   // 26 s: last moment a stage may start; 27.5 s: hard socket wall (2.5 s under the contract's 30 s)
  msgs: [], attempts: {}, violations: {}, trace: [], stages: {}, meta: {},
  integrations: { ai_iot: false, dcm: false, partner_onboarding: false },
};
run.msgs = [
  { role: 'system', content: LIB.prompts.system() },
  { role: 'user', content: LIB.prompts.prefix(run) },
];
msg.run = run;

// test hook: force the catch -> node_degraded path. msg.run.lock_owner is already set above,
// so node_degraded can still release a lock this request took. Only reached with an explicit header.
if (headers['x-debug-throw'] === '1') throw new Error('debug: forced failure');

node.status({ fill: 'blue', shape: 'dot', text: ctx.case_id + ' ' + ctx.seat_id + ' ' + model });
return msg;

const STAGE = "diagnosis";
// One pipeline agent. STAGE is prepended by build.py. Runs the model (with guard retries)
// while the time budget allows, and falls back to the deterministic answer otherwise.
const LIB = global.get('seatlab.lib');
const run = msg.run;
const remaining = () => (run.deadline - Date.now()) / 1000;
let out = null, fallback = false, calls = 0;
const t0 = Date.now();

// agent 5 reuses agent 4's answer when execution was model-owned: that costs no model call at
// all, so it must not be denied for lack of budget.
const free = STAGE === 'learning' && !!run.meta.exec_learn_answer;

if (run.model !== 'off' && !run.meta.llm_down) {
  for (let attempt = 0; attempt < 3 && (free || remaining() > LIB.needSeconds[STAGE]); attempt++) {
    try {
      const r = await LIB.runStage(STAGE, run, { baseUrl: 'http://host.docker.internal:11434', model: run.model });
      calls += r.calls;
      run.stages[STAGE] = r.out;
      const v = LIB.guards[STAGE](run);
      (run.meta.guard_history ||= {})[STAGE] = ((run.meta.guard_history || {})[STAGE] || []).concat([v]);
      run.violations[STAGE] = v;                 // graph/nodes.py::make_guard writes it every attempt,
      if (!v.length) { out = r.out; break; }     // so a passing retry clears the previous violations
      run.attempts[STAGE] = attempt + 1;
      if (free) break;   // M9: a reused answer is deterministic — retrying it can't change the guard's verdict
    } catch (e) {
      (run.meta.errors ||= []).push(STAGE + ': ' + String(e).slice(0, 200));
      // graph/nodes.py: only a connection failure means "Ollama is down"; a deadline timeout must
      // not disable the model for the stages that still have budget.
      if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EHOSTUNREACH|EPIPE|refused/i.test(String(e))) run.meta.llm_down = true;
      break;
    }
  }
}

if (!out) {
  out = LIB.fallback[STAGE](run);
  fallback = true;
  run.violations[STAGE] = [];
}
run.stages[STAGE] = out;
run.trace.push({
  stage: LIB.stageName[STAGE], agent: LIB.agentNo[STAGE], status: 'complete', output: out,
  duration_ms: Date.now() - t0, tool_calls: calls, retries: run.attempts[STAGE] || 0, fallback,
});
if (fallback) run.degraded = true;
node.status({
  fill: fallback ? 'yellow' : 'green', shape: 'dot',
  text: (fallback ? 'fallback' : 'model') + ' ' + Math.round((Date.now() - t0) / 100) / 10 + 's',
});
return msg;

