// Closes the loop: files the second-opinion request, persists the lesson, releases the
// busy lock and renders the submission document.
const LIB = global.get('seatlab.lib');
const run = msg.run;

if (run.stages.nff && run.stages.nff.second_opinion_request) run.integrations.partner_onboarding = true;

const ln = run.stages.learning;
if (ln && ln.lesson) {
  // ponytail: last 200 lessons in a global; the dossier only reads the case's fault family anyway
  const lessons = (global.get('seatlab.lessons') || []).concat([ln.lesson]);
  global.set('seatlab.lessons', lessons.slice(-200));
}

msg.payload = LIB.assemble(run);
if ((msg.req && msg.req.headers['x-debug']) === '1') {
  msg.payload.debug = { model: run.model, errors: run.meta.errors || [], guard_history: run.meta.guard_history || {}, answers: run.meta.answers || {}, timings: run.meta.timings || {}, violations: run.violations };
}
msg.statusCode = 200;
if (run.lock_owner) global.set('seatlab.busy', null);  // I1: only the owner releases the lock
node.status({
  fill: msg.payload.degraded ? 'yellow' : 'green', shape: 'dot',
  text: run.ctx.case_id + ' ' + Math.round((Date.now() - run.started) / 100) / 10 + 's',
});
return msg;

// Catch-all: any node that threw lands here. Finish the run deterministically so the
// contract document is still valid and still 200.
const LIB = global.get('seatlab.lib');
let run = msg.run;
try {
  if (!run) {
    const S = global.get('seatlab.S');
    // I2 belt-and-braces: buildContext already coerces odd input, but if it still throws for a
    // truly unexpected reason, fall back to the default case rather than the minimal error payload.
    let ctx;
    try { ctx = LIB.buildContext(S, msg.payload); } catch (e) { ctx = LIB.buildContext(S, {}); }
    run = {
      ctx, D: LIB.buildDossier(S, ctx.seat_id, ctx.case_row, []), S, model: 'off',
      started: Date.now(), deadline: Date.now() + 1000,
      msgs: [], attempts: {}, violations: {}, trace: [], stages: {}, meta: {},
      integrations: { ai_iot: false, dcm: false, partner_onboarding: false },
    };
  }
  for (const st of ['diagnosis', 'nff', 'plan', 'execution', 'learning']) {
    if (!run.stages[st]) {
      run.stages[st] = LIB.fallback[st](run);
      run.trace.push({
        stage: LIB.stageName[st], agent: LIB.agentNo[st], status: 'complete', output: run.stages[st],
        fallback: true, retries: 0, tool_calls: 0, duration_ms: 0,
      });
    }
  }
  run.degraded = true;
  (run.ctx.degraded_reasons ||= []).push('flow error: ' + ((msg.error && msg.error.message) || 'unknown'));
  msg.payload = LIB.assemble(run);
} catch (e) {
  msg.payload = { team_id: 'airbus-agents', run_id: 'error', degraded: true, error: String(e), trace: [], final_submission: {} };
}
msg.statusCode = 200;
if (msg.run && msg.run.lock_owner) global.set('seatlab.busy', null);  // I1: only the owner releases
node.status({ fill: 'red', shape: 'ring', text: 'degraded' });
return msg;

const S = global.get('seatlab.S') || {};
msg.payload = {ready: !!global.get('seatlab.ready'), version: (global.get('seatlab.lib')||{}).version, seats: S.T && S.T.seats ? S.T.seats.length : 0, lessons: (global.get('seatlab.lessons')||[]).length};
msg.statusCode = 200;
return msg;
